// Raumschiff und schwebende Felsbrocken: Seifenblasen zerplatzen Felsbrocken, Beruehrung beendet die Runde.
export default {
  title: "Raumschiff und schwebende Felsbrocken",
  controls: ["left", "right", "fire"],
  lives: 1,

  init(g) {
    return { ship: { x: 160, y: 590, w: 40, h: 30 }, bubbles: [], rocks: [], parts: [] };
  },

  update(s, input, g) {
    const ship = s.ship;
    if (input.left) ship.x -= 4;
    if (input.right) ship.x += 4;
    ship.x = g.clamp(ship.x, 0, 320);

    if (input.firePressed && s.bubbles.length < 3) {
      s.bubbles.push({ x: ship.x + 20, y: 580, r: 8, hit: false });
      g.sound("shoot");
    }
    for (const b of s.bubbles) b.y -= 6;

    // grosse Felsbrocken erscheinen von oben
    if (g.frame % (g.level >= 2 ? 40 : 50) === 0) {
      s.rocks.push({ x: g.randInt(28, g.W - 28), y: g.TOP - 20, r: 28, big: true, vx: 0 });
    }
    for (const r of s.rocks) {
      r.y += r.big ? 0.8 : 1.2;
      r.x += r.vx;
    }

    // Treffer Blase gegen Felsbrocken
    const alive = [];
    for (const r of s.rocks) {
      let hit = false;
      for (const b of s.bubbles) {
        if (!b.hit && g.hit({ x: b.x, y: b.y, r: b.r }, { x: r.x, y: r.y, r: r.r })) { b.hit = true; hit = true; break; }
      }
      if (!hit) { alive.push(r); continue; }
      for (let i = 0; i < 6; i++) s.parts.push({ x: r.x + g.randInt(-12, 12), y: r.y + g.randInt(-12, 12), t: 8 });
      if (r.big) {
        alive.push({ x: r.x - 12, y: r.y, r: 14, big: false, vx: -0.5 });
        alive.push({ x: r.x + 12, y: r.y, r: 14, big: false, vx: 0.5 });
        g.addScore(10);
        g.sound("pop");
      } else {
        g.addScore(20);
        g.sound("coin");
      }
    }
    s.rocks = alive.filter((r) => r.y <= g.H);
    s.bubbles = s.bubbles.filter((b) => !b.hit && b.y >= g.TOP);

    // Level alle 100 Punkte
    while (g.score >= g.level * 100) g.nextLevel();

    for (const p of s.parts) p.t -= 1;
    s.parts = s.parts.filter((p) => p.t > 0);

    // Beruehrung mit dem Raumschiff beendet die Runde
    const shipC = { x: ship.x + 20, y: ship.y + 15, r: 16 };
    for (const r of s.rocks) {
      if (g.hit(shipC, { x: r.x, y: r.y, r: r.r })) { g.sound("hurt"); g.loseLife(); return; }
    }
  },

  draw(s, d, g) {
    d.clear("cream");
    for (const b of s.bubbles) d.circle(b.x, b.y, b.r, "yellow", { line: true });
    for (const r of s.rocks) d.emoji("🌑", r.x, r.y, r.big ? 60 : 30);
    for (const p of s.parts) d.circle(p.x, p.y, 3, "yellow");
    d.emoji("🚀", s.ship.x + 20, s.ship.y + 15, 36);
  }
};

// Schlange: Die Schlange bewegt sich von selbst, Aepfel machen sie laenger. Wand oder eigener Koerper beendet das Spiel.
// Punkte: 1 je Apfel, 1 je 300 Frames Ueberleben (Ausweichen), 5 Bonuspunkte je Levelaufstieg (nach jeweils 5 Aepfeln).
const CELL = 20, COLS = 18, ROWS = 29, Y0 = 56, START_SPEED = 10, MIN_SPEED = 4, LEVEL_BONUS = 5, SURVIVE = 300;

export default {
  title: "Die Schlange sammelt Äpfel",
  controls: ["up", "down", "left", "right"],
  lives: 1,

  init(g) {
    const s = { body: [], dir: { x: 1, y: 0 }, next: { x: 1, y: 0 }, apple: { x: 0, y: 0 }, wait: 0, eaten: 0, speed: START_SPEED, age: 0 };
    s.body = [{ x: 6, y: 14 }, { x: 5, y: 14 }, { x: 4, y: 14 }];
    placeApple(s, g);
    return s;
  },

  update(s, input, g) {
    s.age += 1;
    if (s.age % SURVIVE === 0) g.addScore(1);   // Ueberleben belohnt: Ausweichen bringt Punkte
    const want = input.up ? { x: 0, y: -1 } : input.down ? { x: 0, y: 1 } : input.left ? { x: -1, y: 0 } : input.right ? { x: 1, y: 0 } : null;
    if (want && !(want.x === -s.dir.x && want.y === -s.dir.y)) s.next = { x: want.x, y: want.y };
    s.wait += 1;
    if (s.wait < s.speed) return;
    s.wait = 0;
    s.dir = { x: s.next.x, y: s.next.y };
    const head = { x: s.body[0].x + s.dir.x, y: s.body[0].y + s.dir.y };
    const crash = head.x < 0 || head.y < 0 || head.x >= COLS || head.y >= ROWS || s.body.some((p) => p.x === head.x && p.y === head.y);
    if (crash) { g.sound("hurt"); g.loseLife(); return; }
    s.body.unshift(head);
    if (head.x === s.apple.x && head.y === s.apple.y) {
      s.eaten += 1;
      g.addScore(1);
      g.sound("coin");
      if (s.speed > MIN_SPEED) s.speed -= 1;
      if (s.eaten % 5 === 0) { g.nextLevel(); g.addScore(LEVEL_BONUS); g.sound("level"); }
      placeApple(s, g);
    } else {
      s.body.pop();
    }
  },

  draw(s, d) {
    d.clear("cream");
    d.rect(0, Y0, COLS * CELL, ROWS * CELL, "yellow", { round: 16, line: true });
    d.emoji("🍎", s.apple.x * CELL + CELL / 2, Y0 + s.apple.y * CELL + CELL / 2, 18);
    s.body.forEach((p, i) => {
      if (i === 0) d.emoji("🐍", p.x * CELL + CELL / 2, Y0 + p.y * CELL + CELL / 2, 20);
      else d.rect(p.x * CELL + 1, Y0 + p.y * CELL + 1, CELL - 2, CELL - 2, i % 2 ? "ink" : "red", { round: 6 });
    });
  }
};

function placeApple(s, g) {
  for (let tries = 0; tries < 200; tries++) {
    const a = { x: g.randInt(0, COLS - 1), y: g.randInt(0, ROWS - 1) };
    if (!s.body.some((p) => p.x === a.x && p.y === a.y)) { s.apple = a; return; }
  }
}

// Ueberhol-Rennen: Rennwagen auf zwei Spuren, fremde Autos ueberholen, Zusammenstoss beendet die Fahrt.
export default {
  title: "Überhol-Rennen auf der Autobahn",
  controls: ["left", "right"],
  lives: 3,

  init(g) {
    return { me: { x: 250, y: 520, w: 40, h: 60 }, cars: [], ueberholt: 0, road: 0 };
  },

  update(s, input, g) {
    if (input.left) s.me.x -= 6;
    if (input.right) s.me.x += 6;
    s.me.x = g.clamp(s.me.x, 70, 250);

    const tempo = 4 + 0.4 * Math.floor(s.ueberholt / 10);
    s.road = (s.road + tempo) % 60;

    const pl = s.me.x < 160 ? 0 : 1;
    if (g.frame >= 30 && g.random() < 0.03) {
      // Meist auf der anderen Spur, damit Ueberholen moeglich ist; manchmal auf der eigenen Spur.
      const lane = g.random() < 0.75 ? 1 - pl : pl;
      s.cars.push({ x: lane === 0 ? 70 : 250, y: -60, w: 40, h: 60, lane, counted: false });
    }

    for (const c of s.cars) {
      c.y += tempo;
      if (g.hit(s.me, c)) { g.sound("lose"); g.gameOver(); return; }
      if (!c.counted && c.y > s.me.y + s.me.h && c.lane !== pl) {
        c.counted = true;
        s.ueberholt += 1;
        g.addScore(1);
        g.sound("pop");
        if (s.ueberholt % 10 === 0) g.nextLevel();
      }
    }
    s.cars = s.cars.filter((c) => c.y < g.H);
  },

  draw(s, d, g) {
    d.clear("cream");
    d.rect(40, g.TOP, 280, g.H - g.TOP, "ink");
    for (let y = g.TOP - 60 + s.road; y < g.H; y += 60) d.rect(176, y, 8, 30, "yellow");
    for (const c of s.cars) d.emoji("🚙", c.x + 20, c.y + 30, 50);
    d.emoji("🏎️", s.me.x + 20, s.me.y + 30, 56);
    d.text("Überholt: " + s.ueberholt, 20, 30, { size: 22, color: "ink", align: "left" });
  }
};

// Wasserballon-Duell: zwei Boote am Teich, Zug um Zug am selben Geraet. Wer trifft, bekommt Punkte.
// Keine Gewalt, kein Blut: nur Wasserballons, Spritzer und Wellen.
// Der Holzsteg liegt links, damit Wuerfe zur Gegenlinie nicht zwangslaeufig an ihm zerplatzen.
const STEG = { x: 40, y: 316, w: 110, h: 14 };

export default {
  title: "Wasserballon-Duell auf dem Teich",
  controls: ["left", "right", "fire"],
  lives: 1,

  init(g) {
    return { spieler: 1, zz: 180, halten: 0, flug: null, spritz: null, treffer: [0, 0], zuege: 0 };
  },

  update(s, input, g) {
    if (s.spritz) { s.spritz.t -= 1; if (s.spritz.t <= 0) s.spritz = null; }

    if (s.flug) {
      const f = s.flug;
      f.t += 1;
      const k = f.t / 30;
      f.x = f.x0 + (f.x1 - f.x0) * k;
      f.y = f.y0 + (f.y1 - f.y0) * k;
      // Steg: der Ballon platzt, kein Punkt
      if (f.y >= STEG.y && f.y <= STEG.y + STEG.h && f.x >= STEG.x && f.x <= STEG.x + STEG.w) {
        g.sound("pop");
        endeZug(s, g, false);
        return;
      }
      if (f.t >= 30) {
        endeZug(s, g, Math.abs(f.x1 - 180) <= 30);
      }
      return;
    }

    // Zielen: Zielmarke bewegen, mit fire werfen
    const dx = (input.right ? 1 : 0) - (input.left ? 1 : 0);
    if (dx !== 0) {
      if (s.halten % 12 === 0) s.zz = g.clamp(s.zz + 10 * dx, 20, 340);
      s.halten += 1;
    } else s.halten = 0;

    if (input.firePressed) {
      const sp = s.spieler;
      s.flug = { sp, x0: 180, y0: sp === 1 ? 150 : 490, x1: s.zz, y1: sp === 1 ? 500 : 140, t: 0, x: 180, y: sp === 1 ? 150 : 490 };
      s.halten = 0;
      g.sound("shoot");
    }
  },

  draw(s, d, g) {
    d.clear("cream");
    d.rect(10, 100, 340, 520, "cream", { round: 24, line: true });
    d.rect(STEG.x, STEG.y, STEG.w, STEG.h, "yellow", { round: 4, line: true });
    d.emoji("⛵", 180, 120, 40);
    d.emoji("🚤", 180, 520, 40);
    if (!s.flug) {
      const ziel = s.spieler === 1 ? 500 : 140;
      d.circle(s.zz, ziel, 7, "ink", { line: true });
    }
    if (s.flug) d.emoji("🎈", s.flug.x, s.flug.y, 26);
    if (s.spritz) d.emoji("💦", 180, s.spritz.y, 40);
    d.text(s.flug ? "Wurf läuft ..." : "Spieler " + s.spieler + " dran", 180, 84, { size: 20, align: "center" });
    d.text("Treffer: " + s.treffer[0] + " : " + s.treffer[1], 180, 610, { size: 18, align: "center" });
    d.text("Zug: " + s.zuege + " / 30", 180, 632, { size: 16, align: "center" });
  }
};

function endeZug(s, g, treffer) {
  const sp = s.flug.sp;
  s.flug = null;
  s.zuege += 1;
  if (treffer) {
    s.treffer[sp - 1] += 1;
    g.addScore(1);
    g.sound("hit");
    s.spritz = { y: sp === 1 ? 520 : 120, t: 40 };
    if (s.treffer[sp - 1] >= 5) { g.win(); return; }
  }
  s.spieler = 3 - sp;
  if (s.zuege >= 30) g.gameOver();
}

// Katze auf den Daechern (nur Spiel-API). Umgesetzt: p1 Springen, p2 Fischgraeten, p3 Luecken und Neustart, p5 Tempo.
// Nicht umgesetzt (ehrlich): p4 (gestreifter Schwanz, gruene Augen: nur das Emoji 🐱 ist moeglich),
// p6 (Ergebnisanzeige nach dem Spiel mit bestem Stand: fehlt).
// Luecken 40 bis 80 px statt 120: bei Tempo 2 ist der Sprung (ca. 37 Frames Flug) sonst nicht schaffbar.
const ROOF_Y = 400, RUN_END = 900;

export default {
  title: "Katze auf den Dächern",
  controls: ["up"],
  lives: 3,

  init(g) {
    const s = { cat: null, roofs: [], fish: 0, held: false, safe: 0 };
    reset(s, g);
    return s;
  },

  update(s, input, g) {
    const c = s.cat;
    if (s.safe > 0) s.safe -= 1;

    // Welt scrollt nach links
    const sp = 2 + 0.5 * (g.level - 1);
    for (const r of s.roofs) r.x -= sp;
    s.roofs = s.roofs.filter((r) => r.x + r.w > -4);
    let last = 0;
    for (const r of s.roofs) last = Math.max(last, r.x + r.w);
    fill(s, g, last);

    // Auf einem Dach bleiben, nur solange es unter der Katze liegt
    if (c.ground && !onRoof(s, c)) c.ground = false;

    // Sprung nur vom Dach und nur beim Druecken (nicht beim Halten)
    if (input.up && !s.held && c.ground) { c.vy = -11; c.ground = false; g.sound("jump"); }
    s.held = !!input.up;

    if (!c.ground) {
      const prev = c.y + c.h;
      c.vy = Math.min(c.vy + 0.6, 14);
      c.y += c.vy;
      for (const r of s.roofs) {
        if (c.vy >= 0 && c.x + c.w > r.x && c.x < r.x + r.w && prev <= r.y && c.y + c.h >= r.y) {
          c.y = r.y - c.h; c.vy = 0; c.ground = true; break;
        }
      }
    }

    // Fischgraeten einsammeln (kein Leben-Verlust)
    for (const r of s.roofs) {
      if (!r.f) continue;
      const fish = { x: r.x + r.w / 2 - 9, y: r.y - 18, w: 18, h: 18 };
      if (g.hit(c, fish)) { r.f = false; s.fish += 1; g.addScore(1); g.sound("coin"); }
    }

    // Sturz durch eine Luecke: ein Leben, Neustart an der Startposition
    if (c.y > g.H) {
      if (s.safe === 0) g.loseLife();
      reset(s, g);
      return;
    }

    if ((g.frame + 1) % 600 === 0) { g.nextLevel(); g.sound("level"); }
  },

  draw(s, d, g) {
    d.clear("cream");
    for (const r of s.roofs) {
      d.rect(r.x, r.y, r.w, 16, "yellow", { round: 6, shadow: true, line: true });
      if (r.f) d.emoji("🐟", r.x + r.w / 2, r.y - 9, 18);
    }
    const c = s.cat;
    d.emoji("🐱", c.x + c.w / 2, c.y + c.h / 2, 30);
    d.text("Fischgräten: " + s.fish, 12, g.H - 16, { size: 20, align: "left" });
  }
};

function reset(s, g) {
  s.cat = { x: 40, y: ROOF_Y - 30, w: 26, h: 30, vy: 0, ground: true };
  s.fish = 0;
  s.safe = 60;
  s.roofs = [];
  for (let x = 0; x < RUN_END; x += 150) s.roofs.push({ x, y: ROOF_Y, w: 150, f: x % 300 === 0 });
  fill(s, g, RUN_END);
}

function fill(s, g, last) {
  while (last < g.W + 60) {
    const r = addRoof(s, g, last + g.randInt(40, 80));
    last = r.x + r.w;
  }
}

function addRoof(s, g, x) {
  const r = { x, y: g.randInt(360, 440), w: g.randInt(90, 150), f: g.random() < 0.5 };
  s.roofs.push(r);
  return r;
}

function onRoof(s, c) {
  return s.roofs.some((r) => Math.abs(r.y - (c.y + c.h)) < 0.5 && c.x + c.w > r.x && c.x < r.x + r.w);
}

// Memory mit 12 Karten (6 Paare), Cursor mit Richtungen, Feuer waehlt. Keine Uhr, nur Zuglimit.
const BILDER = ["🌞", "🌸", "⭐", "❤️", "🏠", "⚽"];
const SPALTEN = 4, ZEILEN = 3, ZELLE = 80, KARTE = 68, X0 = 26, Y0 = 150;
const ZUEGE = 24, WIEDERHOLEN = 12, ZEIGEN = 40;

export default {
  title: "Memory mit 12 bunten Karten",
  controls: ["left", "right", "up", "down", "fire"],
  lives: 1,

  init(g) {
    const karten = [];
    for (const b of BILDER) {
      karten.push({ b, offen: false, paar: false });
      karten.push({ b, offen: false, paar: false });
    }
    for (let i = karten.length - 1; i > 0; i--) {
      const j = g.randInt(0, i);
      const t = karten[i]; karten[i] = karten[j]; karten[j] = t;
    }
    return { karten, cx: 0, cy: 0, halten: 0, wahl: [], zeigen: 0, zuege: 0, paare: 0, fertig: false };
  },

  update(s, input, g) {
    if (s.fertig) return;
    // zwei offene Karten ohne Paar kurz zeigen, dann wieder verdecken
    if (s.zeigen > 0) {
      s.zeigen -= 1;
      if (s.zeigen === 0) {
        for (const i of s.wahl) s.karten[i].offen = false;
        s.wahl = [];
      }
      return;
    }
    // Cursor: sofort beim Druecken, dann alle WIEDERHOLEN Frames solange gehalten
    const dx = (input.right ? 1 : 0) - (input.left ? 1 : 0);
    const dy = (input.down ? 1 : 0) - (input.up ? 1 : 0);
    if (dx !== 0 || dy !== 0) {
      if (s.halten % WIEDERHOLEN === 0) {
        s.cx = g.clamp(s.cx + dx, 0, SPALTEN - 1);
        s.cy = g.clamp(s.cy + dy, 0, ZEILEN - 1);
      }
      s.halten += 1;
    } else s.halten = 0;

    if (!input.firePressed) return;
    const i = s.cy * SPALTEN + s.cx;
    const k = s.karten[i];
    if (k.offen || k.paar) return;
    k.offen = true;
    s.wahl.push(i);
    g.sound("pop");
    if (s.wahl.length < 2) return;

    s.zuege += 1;
    const a = s.karten[s.wahl[0]], b = s.karten[s.wahl[1]];
    if (a.b === b.b) {
      a.paar = true; b.paar = true;
      s.wahl = [];
      s.paare += 1;
      g.addScore(10);
      g.sound("coin");
      if (s.paare === BILDER.length) {
        s.fertig = true;
        g.addScore(Math.max(0, ZUEGE - s.zuege));
        g.win();
        return;
      }
    } else {
      g.addScore(1);
      s.zeigen = ZEIGEN;
    }
    if (s.zuege >= ZUEGE) g.gameOver();
  },

  draw(s, d, g) {
    d.clear("cream");
    d.text("Züge: " + s.zuege + " / " + ZUEGE, g.W / 2, 90, { size: 20, align: "center" });
    for (let i = 0; i < s.karten.length; i++) {
      const k = s.karten[i];
      const x = X0 + (i % SPALTEN) * ZELLE, y = Y0 + Math.floor(i / SPALTEN) * ZELLE;
      if (k.paar) d.rect(x, y, KARTE, KARTE, "cream", { round: 10, line: true });
      else d.rect(x, y, KARTE, KARTE, k.offen ? "cream" : "yellow", { round: 10, shadow: true, line: true });
      if (k.offen || k.paar) d.emoji(k.b, x + KARTE / 2, y + KARTE / 2, 40);
    }
    if (!s.fertig) {
      const cx = X0 + s.cx * ZELLE - 6, cy = Y0 + s.cy * ZELLE - 6;
      d.rect(cx, cy, KARTE + 12, 4, "red");
      d.rect(cx, cy + KARTE + 8, KARTE + 12, 4, "red");
      d.rect(cx, cy, 4, KARTE + 12, "red");
      d.rect(cx + KARTE + 8, cy, 4, KARTE + 12, "red");
    } else {
      d.text("Glückwunsch, schön gemacht!", g.W / 2, g.H / 2, { size: 22, color: "ink", align: "center" });
    }
  }
};

// Tennis gegen den Computer: Echtzeit-Pong. Der Computer steuert links, der Spieler rechts.
// Punkte: jeder Schlag des Spielers gibt 1 Punkt, jeder gewonnene Ballwechsel 5 Punkte.
// Zeitlimit: nach 1190 Frames (ca. 20 s) endet die Partie, wer mehr Ballwechsel gewonnen hat, gewinnt.
export default {
  title: "Tennis gegen den Computer",
  controls: ["up", "down"],
  lives: 1,

  init(g) {
    return { bx: 180, by: 340, vx: g.randInt(0, 1) ? 3 : -3, vy: g.randInt(0, 1) ? 2 : -2, serve: 30, py: 280, cpy: 280, comp: 0, mine: 0, rally: 0, off: 0 };
  },

  update(s, input, g) {
    if (g.frame >= 1190) {
      if (s.mine > s.comp) g.win(); else g.gameOver();
      return;
    }
    const top = g.TOP + 4, bottom = g.H - 84;
    s.py = g.clamp(s.py + (input.down ? 5 : 0) - (input.up ? 5 : 0), top, bottom);
    if (s.serve > 0) {
      s.serve -= 1;
      return;
    }
    // Computer: zielt auf den Ball mit Zufallsversatz, Tempo steigt mit den Ballwechseln
    const tempo = Math.min(2.5 + 0.25 * s.rally, 6);
    const diff = s.by + s.off - 40 - s.cpy;
    s.cpy = g.clamp(s.cpy + Math.max(-tempo, Math.min(tempo, diff)), top, bottom);

    s.bx += s.vx;
    s.by += s.vy;
    if (s.by < g.TOP + 6) { s.by = g.TOP + 6; s.vy = Math.abs(s.vy); }
    else if (s.by > g.H - 16) { s.by = g.H - 16; s.vy = -Math.abs(s.vy); }

    // Schlag links (Computer)
    if (s.vx < 0 && s.bx - 10 <= 34 && s.bx + 10 >= 20 && s.by + 10 >= s.cpy && s.by - 10 <= s.cpy + 80) {
      s.bx = 44;
      hit(s, g, s.cpy);
    }
    // Schlag rechts (Spieler): jeder Schlag gibt einen Punkt
    if (s.vx > 0 && s.bx + 10 >= 326 && s.bx - 10 <= 340 && s.by + 10 >= s.py && s.by - 10 <= s.py + 80) {
      s.bx = 316;
      hit(s, g, s.py);
      g.addScore(1);
      g.sound("hit");
    }

    // Ballwechsel an den Wand hinter einem Schlaeger
    if (s.bx < 0) {
      s.mine += 1;
      g.addScore(5);
      g.sound("coin");
      if (s.mine >= 11) { g.win(); return; }
      reset(s, g, -1);
      return;
    }
    if (s.bx > g.W) {
      s.comp += 1;
      g.sound("lose");
      if (s.comp >= 11) { g.gameOver(); return; }
      reset(s, g, 1);
    }
  },

  draw(s, d, g) {
    d.clear("cream");
    d.line(180, 110, 180, 620, "ink", 2);
    d.text(String(s.comp), 150, 90, { size: 28, color: "ink", align: "center" });
    d.text(String(s.mine), 210, 90, { size: 28, color: "red", align: "center" });
    d.emoji("🏓", 27, s.cpy + 40, 40);
    d.emoji("🏓", 333, s.py + 40, 40);
    d.emoji("🎾", s.bx, s.by, 24);
  }
};

function hit(s, g, paddleY) {
  s.vx = s.vx > 0 ? Math.min(7, s.vx + 0.1) : Math.max(-7, s.vx - 0.1);
  s.vx = -s.vx;
  s.vy = g.clamp(s.vy + (s.by - (paddleY + 40)) / 12, -6, 6);
  s.rally += 1;
  const amp = Math.max(2, 12 - s.rally);
  s.off = g.randInt(-amp, amp);
}

function reset(s, g, dir) {
  s.bx = 180;
  s.by = 340;
  s.vx = dir * 4;
  s.vy = g.randInt(0, 1) ? 2 : -2;
  s.serve = 30;
  s.rally = 0;
  s.off = 0;
}

// Wuerfelspiel fuer 4 Personen am Tisch: reihum wuerfeln, wer zuerst 100 Punkte hat, gewinnt. Eine 1 setzt die Rundenpunkte auf 0.
const X = 12, W = 336, H = 130, Y0 = 60, DY = 145, ZIEL = 100, ZUEGE_MAX = 120;

export default {
  title: "Würfeln bis 100 Punkte",
  controls: ["fire"],
  lives: 1,

  init(g) {
    return { t: [0, 0, 0, 0], rund: [0, 0, 0, 0], letzt: [0, 0, 0, 0], zug: 0, zuege: 0, ende: false, sieger: -1 };
  },

  update(s, input, g) {
    if (s.ende) return;
    if (!input.firePressed) return;
    const z = s.zug;
    const r = g.randInt(1, 6);
    s.zuege += 1;
    s.letzt[z] = r;
    if (r === 1) {
      s.rund[z] = 0;
    } else {
      s.t[z] += r;
      s.rund[z] += r;
      g.addScore(r);
      g.sound("coin");
    }
    if (s.t[z] >= ZIEL) {
      s.sieger = z;
      s.ende = true;
      g.sound("win");
      g.win();
    } else if (s.zuege >= ZUEGE_MAX) {
      s.ende = true;
      g.sound("lose");
      g.gameOver();
    } else {
      s.zug = (z + 1) % 4;
    }
  },

  draw(s, d, g) {
    d.clear("cream");
    d.emoji("🎲", g.W / 2, 26, 48);
    for (let i = 0; i < 4; i++) {
      const y = Y0 + i * DY;
      const aktiv = !s.ende && s.zug === i;
      d.rect(X, y, W, H, aktiv ? "red" : "ink", { round: 14, shadow: true });
      d.rect(X + 4, y + 4, W - 8, H - 8, "cream", { round: 12 });
      d.text("Spieler " + (i + 1), X + 18, y + 26, { size: 22, color: "ink", align: "left" });
      d.text(String(s.t[i]), X + W - 18, y + 26, { size: 28, color: "ink", align: "right" });
      d.text("Runde: " + s.rund[i], X + 18, y + 72, { size: 16, color: "ink", align: "left" });
      const letzt = s.letzt[i] > 0 ? String(s.letzt[i]) : "";
      d.text("Letzter Wurf: " + letzt, X + 18, y + 102, { size: 16, color: "ink", align: "left" });
    }
    if (!s.ende) {
      d.text("Dran: Spieler " + (s.zug + 1) + ", Feuer zum Wuerfeln", g.W / 2, 634, { size: 18, color: "ink", align: "center" });
    }
    if (s.ende && s.sieger >= 0) {
      d.rect(20, 250, 320, 140, "yellow", { round: 20, shadow: true });
      d.text("Gewonnen!", g.W / 2, 300, { size: 40, color: "ink", align: "center" });
      d.text("Spieler " + (s.sieger + 1), g.W / 2, 350, { size: 40, color: "ink", align: "center" });
    }
  }
};

// Kartenspiel gegen den Computer (Runden-Vorlage). Ablegen und Ziehen laufen ueber Cursor und Feuer, nicht ueber Tippen auf Karten.
const STUFEN = ["leicht", "mittel", "schwer"];
const MUSTER = ["Stern", "Herz", "Kreis", "Apfel"];
const EMO = ["⭐", "💗", null, "🍎"];
const MAX_ZUEGE = 30, WIEDERHOLEN = 12;

export default {
  title: "Kartenspiel gegen den Computer",
  controls: ["left", "right", "up", "down", "fire"],
  lives: 1,

  init() {
    return { phase: "menue", schwierigkeit: "mittel", hand: [], comp: [], stapel: [], ablage: null, turn: "spieler", cur: 0, halten: 0, wait: 0, hinweis: "", hinweisT: 0, zuege: 0, ergebnis: "" };
  },

  update(s, input, g) {
    const dx = (input.right ? 1 : 0) - (input.left ? 1 : 0);
    const dy = (input.down ? 1 : 0) - (input.up ? 1 : 0);
    let step = false;
    if (dx === 0 && dy === 0) s.halten = 0;
    else if (s.halten <= 0) { step = true; s.halten = WIEDERHOLEN - 1; }
    else s.halten -= 1;
    if (s.hinweisT > 0) { s.hinweisT -= 1; if (s.hinweisT === 0) s.hinweis = ""; }

    if (s.phase === "menue") {
      if (step) { const i = STUFEN.indexOf(s.schwierigkeit); s.schwierigkeit = STUFEN[g.clamp(i + dx + dy, 0, 2)]; }
      if (input.firePressed) start(s, g);
      return;
    }
    if (s.phase !== "spiel") return;

    const n = s.hand.length;
    s.cur = Math.min(s.cur, n);
    if (s.turn === "computer") {
      s.wait -= 1;
      if (s.wait <= 0) computerZug(s, g);
      return;
    }
    if (step) {
      if (dx !== 0) s.cur = g.clamp(s.cur + dx, 0, n);
      if (dy > 0) s.cur = n;
      else if (dy < 0 && s.cur === n) s.cur = Math.max(0, n - 1);
    }
    if (!input.firePressed) return;
    if (s.cur < n) spielKarte(s, g, s.cur);
    else stapelZug(s, g);
  },

  draw(s, d, g) {
    d.clear("cream");
    if (s.phase === "menue") {
      d.text("Kartenspiel", 180, 150, { size: 32, align: "center" });
      d.text("gegen den Computer", 180, 190, { size: 20, align: "center" });
      d.text("Schwierigkeit", 180, 260, { size: 20, align: "center" });
      STUFEN.forEach((st, i) => d.text(st === s.schwierigkeit ? "> " + st + " <" : st, 180, 300 + i * 40, { size: 24, align: "center" }));
      d.text("Auf/Ab wählt, Feuer startet", 180, 470, { size: 16, align: "center" });
      return;
    }
    if (s.phase === "ende") {
      d.text(s.ergebnis, 180, 300, { size: 44, align: "center" });
      d.text("Züge: " + s.zuege, 180, 360, { size: 20, align: "center" });
      return;
    }
    d.text(s.turn === "spieler" ? "Du bist dran" : "Computer ist dran", 180, 70, { size: 20, align: "center" });
    const cn = s.comp.length;
    for (let i = 0; i < cn; i++) d.rect(rowX(g, cn, 44, 6, i), 100, 44, 60, "yellow", { round: 8, line: true });
    d.rect(70, 236, 64, 92, s.stapel.length > 0 ? "yellow" : "cream", { round: 8, shadow: s.stapel.length > 0, line: true });
    d.text("Stapel: " + s.stapel.length, 102, 345, { size: 16, align: "center" });
    if (s.ablage) drawCard(d, s.ablage, 226, 236, 64, 92);
    if (s.hinweisT > 0) d.text(s.hinweis, 180, 380, { size: 18, align: "center" });
    const hn = s.hand.length;
    for (let i = 0; i < hn; i++) drawCard(d, s.hand[i], rowX(g, hn, 60, 6, i), 440, 60, 88);
    if (s.turn === "spieler") {
      if (s.cur < hn) frame(d, rowX(g, hn, 60, 6, s.cur) - 4, 436, 68, 96);
      else frame(d, 66, 232, 72, 100);
    }
    d.text("Züge: " + s.zuege + " / " + MAX_ZUEGE, 180, 600, { size: 16, align: "center" });
  }
};

function start(s, g) {
  const deck = [];
  for (let m = 0; m < 4; m++) for (let w = 1; w <= 4; w++) deck.push({ m, w });
  for (let i = deck.length - 1; i > 0; i--) { const j = g.randInt(0, i); const t = deck[i]; deck[i] = deck[j]; deck[j] = t; }
  const nimm = (m) => deck.splice(deck.findIndex((c) => c.m === m), 1)[0];
  const rest = () => deck.splice(g.randInt(0, deck.length - 1), 1)[0];
  s.hand = []; s.comp = [];
  for (let m = 0; m < 4; m++) s.hand.push(nimm(m));
  for (let m = 0; m < 4; m++) s.comp.push(nimm(m));
  s.hand.push(rest());
  s.comp.push(rest());
  s.ablage = rest();
  s.stapel = deck;
  s.phase = "spiel"; s.turn = "spieler"; s.cur = 0; s.halten = 0; s.wait = 0;
  s.hinweis = ""; s.hinweisT = 0; s.zuege = 0; s.ergebnis = "";
}

function passt(a, b) { return a.m === b.m || a.w === b.w; }

function spielKarte(s, g, i) {
  const c = s.hand[i];
  if (!passt(c, s.ablage)) { s.hinweis = "Passt nicht"; s.hinweisT = 60; g.sound("hurt"); return; }
  s.hand.splice(i, 1);
  s.ablage = c;
  g.addScore(10);
  g.sound("pop");
  if (s.hand.length === 0) return ende(s, g, true);
  endZug(s, g, "computer");
}

function stapelZug(s, g) {
  if (s.stapel.length === 0) {
    if (s.hand.some((c) => passt(c, s.ablage))) { s.hinweis = "Stapel ist leer"; s.hinweisT = 60; return; }
    s.hinweis = "Keine Karte passt, Zug aussetzen"; s.hinweisT = 60;
    endZug(s, g, "computer");
    return;
  }
  s.hand.push(s.stapel.pop());
  g.addScore(2);
  g.sound("coin");
  s.hinweis = "Du ziehst eine Karte"; s.hinweisT = 60;
  endZug(s, g, "computer");
}

function computerZug(s, g) {
  const idx = [];
  s.comp.forEach((c, i) => { if (passt(c, s.ablage)) idx.push(i); });
  if (idx.length > 0) {
    let pick = idx[0];
    if (s.schwierigkeit === "leicht") pick = idx[g.randInt(0, idx.length - 1)];
    else if (s.schwierigkeit === "schwer") {
      let best = -1;
      for (const i of idx) {
        const k = s.comp.filter((c) => c.m === s.comp[i].m).length;
        if (k > best) { best = k; pick = i; }
      }
    }
    const c = s.comp.splice(pick, 1)[0];
    s.ablage = c;
    s.hinweis = "Computer legt " + MUSTER[c.m] + " " + c.w; s.hinweisT = 60;
    g.sound("pop");
    if (s.comp.length === 0) return ende(s, g, false);
    endZug(s, g, "spieler");
  } else {
    if (s.stapel.length > 0) { s.comp.push(s.stapel.pop()); s.hinweis = "Computer zieht eine Karte"; }
    else s.hinweis = "Computer passt";
    s.hinweisT = 60;
    endZug(s, g, "spieler");
  }
}

function endZug(s, g, next) {
  s.zuege += 1;
  if (s.zuege >= MAX_ZUEGE) return ende(s, g, s.hand.length < s.comp.length);
  s.turn = next;
  s.cur = Math.min(s.cur, s.hand.length);
  if (next === "computer") s.wait = 40;
}

function ende(s, g, sieg) {
  s.phase = "ende";
  s.ergebnis = sieg ? "Sieg!" : "Niederlage";
  if (sieg) g.win(); else g.gameOver();
}

function rowX(g, n, w, gap, i) {
  return (g.W - (n * (w + gap) - gap)) / 2 + i * (w + gap);
}

function frame(d, x, y, w, h) {
  d.rect(x, y, w, 4, "red"); d.rect(x, y + h - 4, w, 4, "red");
  d.rect(x, y, 4, h, "red"); d.rect(x + w - 4, y, 4, h, "red");
}

function drawCard(d, c, x, y, w, h) {
  d.rect(x, y, w, h, "cream", { round: 8, line: true });
  if (c.m === 2) d.circle(x + w / 2, y + h / 2 - 10, 14, "yellow", { line: true });
  else d.emoji(EMO[c.m], x + w / 2, y + h / 2 - 10, 30);
  d.text(String(c.w), x + w / 2, y + h - 18, { size: 18, align: "center", color: "ink" });
}

// Rennspiel aus der Vogelperspektive: zwei Spuren, Autos kommen entgegen, Ueberholen zaehlt Punkte.
const TOP_Y = 520;

export default {
  title: "Überholen auf der Autobahn",
  controls: ["left", "right"],
  lives: 1,

  init(g) {
    return { lane: 1, x: 260, cars: [], dichte: 0.035, ueberholt: 0 };
  },

  update(s, input, g) {
    if (input.left) s.lane = 0;
    if (input.right) s.lane = 1;
    const tx = s.lane === 0 ? 100 : 260;
    const dx = tx - s.x;
    s.x += Math.sign(dx) * Math.min(6, Math.abs(dx));

    if (g.frame > 0 && g.frame % 300 === 0) s.dichte = g.random() < 0.5 ? 0.008 : 0.035;
    if (g.frame % 30 === 0) g.addScore(1);

    for (const c of s.cars) c.y += 3;

    for (const c of s.cars) {
      if (!c.gez && c.lane !== s.lane && c.y > TOP_Y + 35) {
        c.gez = true;
        s.ueberholt += 1;
        g.addScore(1);
        g.sound("pop");
      }
    }

    for (const c of s.cars) {
      if (c.lane === s.lane && Math.abs(c.y - TOP_Y) < 70) {
        s.cars = [];
        g.sound("hurt");
        g.loseLife();
        return;
      }
    }

    if (s.cars.length < 30) {
      for (const lane of [0, 1]) {
        if (g.random() < s.dichte) s.cars.push({ x: lane === 0 ? 100 : 260, y: -80, lane, gez: false });
      }
    }
    s.cars = s.cars.filter((c) => c.y <= g.H + 80);
  },

  draw(s, d, g) {
    d.clear("cream");
    d.rect(40, 48, 120, 592, "yellow", { round: 8 });
    d.rect(200, 48, 120, 592, "yellow", { round: 8 });
    for (const c of s.cars) d.emoji("🚙", c.x, c.y, 34);
    d.emoji("🏎️", s.x, TOP_Y, 36);
    d.text("Ueberholt: " + s.ueberholt, 352, 30, { size: 18, align: "right" });
  }
};

// Die Apfel-Schlange: Schlange auf einem Raster, jeder Apfel macht sie laenger und schneller.
// Raender sind verbunden. Beisst der Kopf in den eigenen Koerper, endet das Spiel.
// Zeitlimit: nach 2400 Frames (40 s) endet die Runde mit dem Punktestand.
const CELL = 20, COLS = 18, ROWS = 29, Y0 = 56, LIMIT = 2400;
const START_APPLE = { x: 9, y: 14 };

export default {
  title: "Die Apfel-Schlange",
  controls: ["up", "down", "left", "right"],
  lives: 1,

  init(g) {
    const s = { body: [], dir: { x: 1, y: 0 }, next: { x: 1, y: 0 }, apple: { x: 0, y: 0 }, wait: 0, eaten: 0, alter: 0 };
    reset(s, g);
    return s;
  },

  update(s, input, g) {
    s.alter += 1;
    if (s.alter >= LIMIT) { g.gameOver(); return; }

    const want = input.up ? { x: 0, y: -1 } : input.down ? { x: 0, y: 1 } : input.left ? { x: -1, y: 0 } : input.right ? { x: 1, y: 0 } : null;
    if (want && !(want.x === -s.dir.x && want.y === -s.dir.y)) s.next = { x: want.x, y: want.y };

    s.wait += 1;
    if (s.wait < Math.max(4, 9 - g.level)) return;
    s.wait = 0;

    s.dir = { x: s.next.x, y: s.next.y };
    const hx = (s.body[0].x + s.dir.x + COLS) % COLS;
    const hy = (s.body[0].y + s.dir.y + ROWS) % ROWS;
    const eat = hx === s.apple.x && hy === s.apple.y;
    const teil = eat ? s.body : s.body.slice(0, -1);
    if (teil.some((p) => p.x === hx && p.y === hy)) {
      g.sound("hurt");
      g.loseLife();
      reset(s, g);
      return;
    }
    s.body.unshift({ x: hx, y: hy });
    if (eat) {
      g.addScore(10);
      g.sound("coin");
      s.eaten += 1;
      g.nextLevel();
      placeApple(s, g);
    } else {
      s.body.pop();
    }
  },

  draw(s, d) {
    d.clear("cream");
    d.rect(0, Y0, COLS * CELL, ROWS * CELL, "yellow", { round: 16, line: true });
    d.emoji("🍎", s.apple.x * CELL + CELL / 2, Y0 + s.apple.y * CELL + CELL / 2, 18);
    s.body.forEach((p, i) => {
      d.emoji(i === 0 ? "🐍" : "🟢", p.x * CELL + CELL / 2, Y0 + p.y * CELL + CELL / 2, 18);
    });
  }
};

function reset(s, g) {
  s.body = [{ x: 6, y: 14 }, { x: 5, y: 14 }, { x: 4, y: 14 }];
  s.dir = { x: 1, y: 0 };
  s.next = { x: 1, y: 0 };
  s.wait = 0;
  s.eaten = 0;
  s.alter = 0;
  s.apple = { x: START_APPLE.x, y: START_APPLE.y };
}

function placeApple(s, g) {
  for (let tries = 0; tries < 200; tries++) {
    const a = { x: g.randInt(0, COLS - 1), y: g.randInt(0, ROWS - 1) };
    if (!s.body.some((p) => p.x === a.x && p.y === a.y)) { s.apple = a; return; }
  }
  for (let y = 0; y < ROWS; y++) {
    for (let x = 0; x < COLS; x++) {
      if (!s.body.some((p) => p.x === x && p.y === y)) { s.apple = { x, y }; return; }
    }
  }
}

// Katze auf den Daechern: Jump and Run ueber Daecher, Fischgraeten sammeln, Luecke = Lauf vorbei.
// Nicht umgesetzt: Ende-Anzeige mit Fischgraeten-Zahl und Neustart-Knopf (p6, nicht machbar).
const SCROLL = 3, GAP = 50, ROOF_Y = 600, ROOF_H = 40;

export default {
  title: "Katze auf den Dächern",
  controls: ["left", "right", "fire"],
  lives: 1,

  init(g) {
    return {
      me: { x: 30, y: 576, w: 24, h: 24, vx: 0, vy: 0, ground: true },
      roofs: [
        { x: 0, y: ROOF_Y, w: 120, h: ROOF_H },
        { x: 170, y: ROOF_Y, w: 120, h: ROOF_H },
        { x: 340, y: ROOF_Y, w: 140, h: ROOF_H },
        { x: 530, y: ROOF_Y, w: 130, h: ROOF_H },
        { x: 700, y: ROOF_Y, w: 160, h: ROOF_H }
      ],
      fische: [{ x: 100, y: 552, got: false }],
      scroll: 0
    };
  },

  update(s, input, g) {
    const me = s.me;
    me.vx = input.left ? -3 : input.right ? 3 : 0;
    me.x = g.clamp(me.x + me.vx, 0, g.W - me.w);

    // Daecher und Fische scrollen nach links; neue Daecher rechts nachliefern
    for (const r of s.roofs) r.x -= SCROLL;
    for (const f of s.fische) f.x -= SCROLL;
    s.scroll += SCROLL;
    s.roofs = s.roofs.filter((r) => r.x + r.w > -10);
    s.fische = s.fische.filter((f) => f.x > -30 && !f.got);
    let last = s.roofs[s.roofs.length - 1];
    while (last.x + last.w < g.W + 60) {
      const x = last.x + last.w + GAP, w = g.randInt(80, 160);
      last = { x, y: ROOF_Y, w, h: ROOF_H };
      s.roofs.push(last);
      if (g.random() < 0.5) s.fische.push({ x: x + 30, y: 552, got: false });
    }

    const feet = () => me.y + me.h;

    // Sprung
    if ((input.fire || input.firePressed) && me.ground) {
      me.vy = -10; me.ground = false; g.sound("jump");
    }

    // Auf dem Dach bleiben nur, solange noch ein Dach unter den Fuessen ist
    if (me.ground) {
      const on = s.roofs.some((r) => me.x + me.w > r.x && me.x < r.x + r.w && r.y === feet());
      if (!on) { me.ground = false; me.vy = 0; }
    }

    // Schwerkraft und Landung von oben
    me.vy = Math.min(me.vy + 0.5, 12);
    const oldBottom = feet();
    me.y += me.vy;
    if (me.vy >= 0) {
      for (const r of s.roofs) {
        const over = me.x + me.w > r.x && me.x < r.x + r.w;
        if (over && oldBottom <= r.y && feet() >= r.y) { me.y = r.y - me.h; me.vy = 0; me.ground = true; }
      }
    }

    // Fischgraeten einsammeln
    for (const f of s.fische) {
      if (!f.got && g.hit({ x: f.x, y: f.y, w: 24, h: 36 }, { x: me.x, y: me.y, w: me.w, h: me.h })) {
        f.got = true; g.addScore(1); g.sound("coin");
      }
    }
    s.fische = s.fische.filter((f) => !f.got);

    // Gefallen: Lauf vorbei
    if (me.y > g.H) { g.sound("hurt"); g.loseLife(); return; }
  },

  draw(s, d, g) {
    d.clear("cream");
    for (const r of s.roofs) {
      d.rect(r.x, r.y, r.w, r.h, "yellow", { round: 6, line: true });
      for (let bx = r.x + 8; bx < r.x + r.w - 14; bx += 24) {
        const c = Math.floor(bx / 24) % 2 ? "red" : "ink";
        d.rect(bx, r.y + 6, 14, 8, c, { round: 2 });
        d.rect(bx + 12, r.y + 20, 14, 8, c === "red" ? "ink" : "red", { round: 2 });
      }
    }
    for (const f of s.fische) d.emoji("🐟", f.x + 12, f.y + 12, 24);
    d.emoji("🐈", s.me.x + 12, s.me.y + 12, 30);
  }
};

// Raumschiff gegen platzende Felsbrocken (nur Spiel-API, keine Importe).
// Seifenblasen schiessen, grosse Felsbrocken brauchen drei Treffer, kleine einen. Ein Zusammenstoss beendet die Runde.
// Nach links 4 px je Frame, nach rechts 2 px je Frame (Ausgleich, damit ein Hin-und-her ehrlich spuerbar nach links fuehrt).
const SPEED_BASE = 1.5, SPEED_LEVEL = 0.2, COOL = 15, SHOT_SPEED = 6, POP_TIME = 12;

export default {
  title: "Raumschiff gegen platzende Felsbrocken",
  controls: ["left", "right", "fire"],
  lives: 1,

  init(g) {
    return { ship: { x: 162, y: 562, w: 36, h: 36 }, rocks: [], shots: [], pops: [], cool: 0, spawn: 30 };
  },

  update(s, input, g) {
    // Level alle 1800 Frames
    if (g.frame > 0 && g.frame % 1800 === 0) { g.nextLevel(); g.sound("level"); }

    // Schiff bewegen
    if (input.left) s.ship.x -= 4;
    if (input.right) s.ship.x += 2;
    s.ship.x = g.clamp(s.ship.x, 4, 320);

    // Schuss mit Abkuehlung (Druck oder gehalten)
    if (s.cool > 0) s.cool -= 1;
    if ((input.firePressed || input.fire) && s.cool === 0) {
      s.shots.push({ x: s.ship.x + 18, y: s.ship.y, r: 8, dead: false });
      s.cool = COOL;
      g.sound("shoot");
    }
    for (const b of s.shots) b.y -= SHOT_SPEED;

    // Felsbrocken spawnen
    s.spawn -= 1;
    if (s.spawn <= 0) {
      const big = g.random() < 0.4;
      const r = big ? 26 : 14;
      s.rocks.push({ x: g.randInt(30, g.W - 30), y: g.TOP + r, r, big, hits: big ? 3 : 1, dead: false });
      s.spawn = g.randInt(60, 90);
    }
    const speed = SPEED_BASE + SPEED_LEVEL * g.level;
    for (const r of s.rocks) r.y += speed;

    // Treffer Blase gegen Felsbrocken (jeder Treffer gibt Zwischenpunkte)
    for (const b of s.shots) {
      for (const r of s.rocks) {
        if (b.dead || r.dead) continue;
        if (g.dist(b, r) < b.r + r.r) {
          b.dead = true;
          r.hits -= 1;
          if (r.hits <= 0) {
            r.dead = true;
            g.addScore(r.big ? 30 : 10);
            s.pops.push({ x: r.x, y: r.y, t: POP_TIME });
            g.sound("pop");
          } else {
            g.addScore(2);
            g.sound("hit");
          }
        }
      }
    }

    // Zusammenstoss Schiff gegen Felsbrocken: Runde endet
    for (const r of s.rocks) {
      if (!r.dead && g.hit(s.ship, r)) { g.gameOver(); return; }
    }

    // Aufraeumen
    s.rocks = s.rocks.filter((r) => !r.dead && r.y - r.r < g.H);
    s.shots = s.shots.filter((b) => !b.dead && b.y >= g.TOP);
    for (const p of s.pops) p.t -= 1;
    s.pops = s.pops.filter((p) => p.t > 0);
  },

  draw(s, d, g) {
    d.clear("cream");
    for (const r of s.rocks) d.emoji("🪨", r.x, r.y, r.big ? 52 : 28);
    for (const b of s.shots) d.emoji("🫧", b.x, b.y, 20);
    for (const p of s.pops) d.emoji("✨", p.x, p.y, 30);
    d.emoji("🚀", s.ship.x + 18, s.ship.y + 18, 36);
  }
};

// Ball-Duell gegen den Computer: Pong mit Schlaegern links (du) und rechts (Computer).
export default {
  title: "Ball-Duell gegen den Computer",
  controls: ["up", "down"],
  lives: 1,

  init(g) {
    return { py: 330, cy: 330, cs: 3, t: 0, mine: 0, bx: 180, by: 330, vx: 3, vy: 2 };
  },

  update(s, input, g) {
    s.t += 1;
    if (input.up) s.py -= 5;
    if (input.down) s.py += 5;
    s.py = g.clamp(s.py, g.TOP + 30, g.H - 30);

    if (s.t % 120 === 0) s.cs = g.randInt(1, 6);
    if (s.cy < s.by) s.cy += s.cs; else s.cy -= s.cs;
    s.cy = g.clamp(s.cy, g.TOP + 30, g.H - 30);

    s.bx += s.vx;
    s.by += s.vy;
    if (s.by <= g.TOP + 7) { s.by = g.TOP + 7; s.vy = Math.abs(s.vy); }
    if (s.by >= g.H - 7) { s.by = g.H - 7; s.vy = -Math.abs(s.vy); }

    const ball = { x: s.bx, y: s.by, r: 7 };
    if (s.vx < 0 && g.hit(ball, { x: 12, y: s.py - 30, w: 36, h: 60 })) bounce(s, g, s.py);
    else if (s.vx > 0 && g.hit(ball, { x: 312, y: s.cy - 30, w: 36, h: 60 })) bounce(s, g, s.cy);

    if (s.bx < 0) {
      g.addScore(1);
      g.sound("lose");
      if (g.score >= 5) { g.gameOver(); return; }
      reset(s, g);
    } else if (s.bx > g.W) {
      s.mine += 1;
      g.sound("coin");
      if (s.mine >= 5) { g.win(); return; }
      reset(s, g);
    }
  },

  draw(s, d, g) {
    d.clear("cream");
    for (let y = g.TOP; y < g.H; y += 24) d.rect(178, y, 4, 12, "yellow");
    d.emoji("🏓", 30, s.py, 48);
    d.emoji("🏓", 330, s.cy, 48);
    d.circle(s.bx, s.by, 7, "red");
    d.text("Du: " + s.mine, 16, 30, { size: 20, color: "ink", align: "left" });
    d.text("Computer: " + g.score, g.W - 16, 30, { size: 20, color: "ink", align: "right" });
  }
};

function bounce(s, g, py) {
  s.vx = -s.vx;
  const sp = Math.min(Math.abs(s.vx) + 0.2, 8);
  s.vx = s.vx < 0 ? -sp : sp;
  s.vy = g.clamp((s.by - py) * 0.15, -5, 5);
}

function reset(s, g) {
  s.bx = 180;
  s.by = 330;
  s.vx = g.randInt(0, 1) === 0 ? -3 : 3;
  s.vy = g.randInt(0, 1) === 0 ? -2 : 2;
}

// Wuerfelspiel fuer 4 Spieler am selben Geraet, Zug fuer Zug. Zwei Wuerfel, Summe als Punkte.
// Eine 1 mit einer anderen Zahl zaehlt nicht. Wer zuerst 100 Punkte hat, gewinnt.
const DICE = ["⚀", "⚁", "⚂", "⚃", "⚄", "⚅"];
const LAMPS = [[30, 140], [80, 170], [130, 132], [180, 178], [230, 132], [280, 170], [330, 140], [55, 188]];
const SCHIRME = [60, 180, 300];
const ZIEL = 100, ZEIT = 60, ZUEGE_MAX = 40;

export default {
  title: "Würfeln bis 100 am Tisch",
  controls: ["fire"],
  lives: 1,

  init(g) {
    return { namen: ["Spieler 1", "Spieler 2", "Spieler 3", "Spieler 4"], scores: [0, 0, 0, 0], cur: 0, phase: "wurf", timer: 0, w1: 0, w2: 0, zuege: 0, sieger: -1 };
  },

  update(s, input, g) {
    if (s.phase === "ende") return;
    if (s.phase === "zeige") {
      s.timer -= 1;
      if (s.timer > 0) return;
      if (s.zuege >= ZUEGE_MAX) { g.gameOver(); return; }
      s.cur = (s.cur + 1) % 4;
      s.phase = "wurf";
      return;
    }
    if (!input.firePressed) return;
    s.w1 = g.randInt(1, 6);
    s.w2 = g.randInt(1, 6);
    s.zuege += 1;
    s.phase = "zeige";
    s.timer = ZEIT;
    if ((s.w1 === 1 || s.w2 === 1) && s.w1 !== s.w2) return;
    const summe = s.w1 + s.w2;
    s.scores[s.cur] += summe;
    g.addScore(summe);
    g.sound("coin");
    if (s.scores[s.cur] >= ZIEL) {
      s.sieger = s.cur;
      s.phase = "ende";
      g.sound("win");
      g.win();
    }
  },

  draw(s, d, g) {
    d.clear("cream");
    d.rect(0, 580, g.W, 60, "yellow");
    for (const [x, y] of LAMPS) d.emoji("🏮", x, y, 30);
    for (const x of SCHIRME) d.emoji("⛱️", x, 600, 40);
    for (let i = 0; i < 4; i++) {
      const x0 = 6 + i * 88, aktiv = i === s.cur && s.phase !== "ende";
      d.rect(x0, 50, 84, 58, aktiv ? "yellow" : "cream", { round: 10, line: true });
      d.text(s.namen[i], x0 + 42, 64, { size: 13, color: "ink", align: "center" });
      d.text(String(s.scores[i]), x0 + 42, 84, { size: 20, color: "red", align: "center" });
      if (aktiv) d.text("am Zug", x0 + 42, 100, { size: 11, color: "ink", align: "center" });
    }
    if (s.zuege > 0) {
      d.emoji(DICE[s.w1 - 1], 130, 390, 80);
      d.emoji(DICE[s.w2 - 1], 230, 390, 80);
      d.text("Augen", 180, 325, { size: 20, color: "ink", align: "center" });
    }
    d.text("Am Zug: " + s.namen[s.cur], 180, 445, { size: 14, color: "ink", align: "center" });
    d.rect(30, 470, 300, 120, "red", { round: 20, shadow: true });
    d.text("Würfeln", 180, 520, { size: 32, color: "cream", align: "center" });
    if (s.phase === "ende") {
      d.rect(40, 250, 280, 100, "yellow", { round: 16, shadow: true, line: true });
      d.text("Sieg: " + s.namen[s.sieger], 180, 290, { size: 26, color: "ink", align: "center" });
    }
  }
};

// Bunte Memory-Karten: 6 Paare gemalter Symbole, 12 verdeckte Karten. Feuer dreht um, Cursor mit Richtungen.
// Spielende: Zuglimit, Zeitlimit oder Ruhezeit nach dem Finale (Text bleibt sichtbar).
const BILDER = ["🌞", "🌸", "⛵", "🐸", "🍓", "🎈"];
const SPALTEN = 3, ZEILEN = 4, ZELLE = 76, KARTE = 68, X0 = 28, Y0 = 120;
const ZUEGE = 24, WIEDERHOLEN = 12, ZEIGEN = 120, DAUER = 2400, RUHE = 900;

export default {
  title: "Bunte Memory-Karten",
  controls: ["left", "right", "up", "down", "fire"],
  lives: 1,

  init(g) {
    const s = { karten: [], cx: 0, cy: 0, halten: 0, wahl: [], zeigen: 0, zuege: 0, paare: 0, fertig: false, dauer: 0, ruhe: 0 };
    mische(s, g);
    return s;
  },

  update(s, input, g) {
    if (s.fertig) {
      s.ruhe += 1;
      if (input.firePressed) { mische(s, g); return; }
      if (s.ruhe >= RUHE) g.gameOver();
      return;
    }
    s.dauer += 1;
    if (s.dauer >= DAUER) { g.gameOver(); return; }
    // zwei offene Karten ohne Paar: kurz zeigen, dann wieder verdecken
    if (s.zeigen > 0) {
      s.zeigen -= 1;
      if (s.zeigen === 0) {
        for (const i of s.wahl) s.karten[i].offen = false;
        s.wahl = [];
      }
      return;
    }
    // Cursor: sofort beim Druecken, dann alle WIEDERHOLEN Frames solange gehalten
    const dx = (input.right ? 1 : 0) - (input.left ? 1 : 0);
    const dy = (input.down ? 1 : 0) - (input.up ? 1 : 0);
    if (dx !== 0 || dy !== 0) {
      if (s.halten % WIEDERHOLEN === 0) {
        s.cx = g.clamp(s.cx + dx, 0, SPALTEN - 1);
        s.cy = g.clamp(s.cy + dy, 0, ZEILEN - 1);
      }
      s.halten += 1;
    } else s.halten = 0;

    if (!input.firePressed) return;
    const i = s.cy * SPALTEN + s.cx;
    const k = s.karten[i];
    if (k.offen || k.weg) return;
    k.offen = true;
    s.wahl.push(i);
    g.sound("pop");
    if (s.wahl.length < 2) return;

    s.zuege += 1;
    const a = s.karten[s.wahl[0]], b = s.karten[s.wahl[1]];
    if (a.b === b.b) {
      a.weg = true; b.weg = true;
      s.wahl = [];
      s.paare += 1;
      g.addScore(10);
      g.sound("coin");
      if (s.paare === BILDER.length) { s.fertig = true; s.ruhe = 0; return; }
    } else {
      g.addScore(1);
      s.zeigen = ZEIGEN;
    }
    if (s.zuege >= ZUEGE) g.gameOver();
  },

  draw(s, d, g) {
    d.clear("cream");
    d.text("Züge: " + s.zuege + " / " + ZUEGE, g.W / 2, 64, { size: 20, align: "center" });
    for (let i = 0; i < s.karten.length; i++) {
      const k = s.karten[i];
      const x = X0 + (i % SPALTEN) * ZELLE, y = Y0 + Math.floor(i / SPALTEN) * ZELLE;
      if (k.weg) { d.rect(x, y, KARTE, KARTE, "cream", { round: 10, line: true }); continue; }
      d.rect(x, y, KARTE, KARTE, k.offen ? "cream" : "yellow", { round: 10, shadow: true, line: true });
      if (k.offen) d.emoji(k.b, x + KARTE / 2, y + KARTE / 2, 40);
    }
    if (!s.fertig) {
      const cx = X0 + s.cx * ZELLE - 4, cy = Y0 + s.cy * ZELLE - 4;
      d.rect(cx, cy, ZELLE, 4, "red"); d.rect(cx, cy + ZELLE - 4, ZELLE, 4, "red");
      d.rect(cx, cy, 4, ZELLE, "red"); d.rect(cx + ZELLE - 4, cy, 4, ZELLE, "red");
    } else {
      d.text("Gut gemacht", g.W / 2, 90, { size: 28, align: "center" });
      d.text("Neue Runde mit Feuer", g.W / 2, 470, { size: 20, align: "center" });
    }
  }
};

function mische(s, g) {
  const karten = [];
  for (const b of BILDER) {
    karten.push({ b, offen: false, weg: false });
    karten.push({ b, offen: false, weg: false });
  }
  for (let i = karten.length - 1; i > 0; i--) {
    const j = g.randInt(0, i);
    const t = karten[i]; karten[i] = karten[j]; karten[j] = t;
  }
  s.karten = karten;
  s.cx = 0; s.cy = 0; s.halten = 0; s.wahl = []; s.zeigen = 0;
  s.zuege = 0; s.paare = 0; s.fertig = false; s.dauer = 0; s.ruhe = 0;
}

// Gummibaerchen-Schaetzspiel: 3 Runden, Tipp per Pfeiltasten, Computer schaetzt mit. Naehere Schaetzung gewinnt die Runde.
export default {
  title: "Gummibärchen-Schätzspiel",
  controls: ["up", "down", "fire"],
  lives: 1,

  init(g) {
    const glas = g.randInt(20, 80);
    return {
      runde: 1, glas, tipp: 50,
      komp: g.clamp(glas + g.randInt(-12, 12), 0, 200),
      siegSp: 0, siegKomp: 0, phase: "tipp", zaehler: 0, halten: 0,
      msg: "Schätze die Anzahl!"
    };
  },

  update(s, input, g) {
    if (s.phase === "zeigen") {
      s.zaehler -= 1;
      if (s.zaehler > 0) return;
      if (s.runde < 3) {
        s.runde += 1;
        s.glas = g.randInt(20, 80);
        s.komp = g.clamp(s.glas + g.randInt(-12, 12), 0, 200);
        s.tipp = 50;
        s.phase = "tipp";
        s.msg = "Neue Runde: Schätze!";
        return;
      }
      if (s.siegSp >= 2) { s.msg = "Gesamtsieger: du!"; g.win(); }
      else { s.msg = "Gesamtsieger: Computer"; g.gameOver(); }
      return;
    }

    const dir = (input.up ? 1 : 0) - (input.down ? 1 : 0);
    if (dir !== 0) {
      if (s.halten % 10 === 0) s.tipp = g.clamp(s.tipp + dir, 0, 200);
      s.halten += 1;
    } else s.halten = 0;

    if (!input.firePressed) return;

    g.addScore(1);
    const p = Math.abs(s.tipp - s.glas);
    const k = Math.abs(s.komp - s.glas);
    if (p < k) { s.siegSp += 1; g.addScore(10); s.msg = "Runde an dich"; g.sound("coin"); }
    else if (k < p) { s.siegKomp += 1; s.msg = "Runde an den Computer"; g.sound("pop"); }
    else s.msg = "Gleichstand, keiner gewinnt";
    s.phase = "zeigen";
    s.zaehler = 120;
  },

  draw(s, d) {
    d.clear("cream");
    d.text("Runde " + s.runde + " von 3", 180, 80, { size: 20, align: "center" });
    d.rect(110, 120, 140, 200, "cream", { round: 12, line: true });
    for (let i = 0; i < s.glas; i++) {
      const col = i % 8, row = Math.floor(i / 8);
      d.circle(120 + col * 16, 130 + row * 16, 6, "red");
    }
    if (s.phase === "tipp") {
      d.text("Dein Tipp: " + s.tipp, 180, 380, { size: 24, align: "center" });
    } else {
      d.text("Dein Tipp: " + s.tipp + "  Computer: " + s.komp + "  Glas: " + s.glas, 180, 400, { size: 16, align: "center" });
      d.text(s.msg, 180, 430, { size: 20, align: "center" });
      if (s.runde === 3) d.text("Gesamt: " + s.siegSp + " : " + s.siegKomp, 180, 470, { size: 20, align: "center" });
    }
    d.emoji("🍬", 180, 440, 48);
  }
};

// Schlange: Aepfel fressen, Wand oder eigener Koerper beendet das Spiel. Steuerung: Pfeile oder Wischen.
const CELL = 20, COLS = 18, ROWS = 29, Y0 = 56;

export default {
  title: "Die Schlange sucht Aepfel",
  controls: ["up", "down", "left", "right"],
  lives: 1,

  init(g) {
    const s = { body: [], dir: { x: 1, y: 0 }, next: { x: 1, y: 0 }, apple: { x: 0, y: 0 }, wait: 0 };
    reset(s, g);
    return s;
  },

  update(s, input, g) {
    const want = input.up ? { x: 0, y: -1 } : input.down ? { x: 0, y: 1 } : input.left ? { x: -1, y: 0 } : input.right ? { x: 1, y: 0 } : null;
    if (want && !(want.x === -s.dir.x && want.y === -s.dir.y)) s.next = want;
    s.wait += 1;
    if (s.wait < Math.max(4, 9 - Math.floor(g.frame / 600))) return;
    s.wait = 0;
    s.dir = { x: s.next.x, y: s.next.y };
    const head = { x: s.body[0].x + s.dir.x, y: s.body[0].y + s.dir.y };
    const crash = head.x < 0 || head.y < 0 || head.x >= COLS || head.y >= ROWS || s.body.some((p) => p.x === head.x && p.y === head.y);
    if (crash) { g.sound("hurt"); g.gameOver(); return; }
    s.body.unshift(head);
    if (head.x === s.apple.x && head.y === s.apple.y) {
      g.addScore(1); g.sound("coin");
      placeApple(s, g);
    } else {
      s.body.pop();
    }
  },

  draw(s, d) {
    d.clear("cream");
    d.rect(0, Y0, COLS * CELL, ROWS * CELL, "yellow", { round: 16, line: true });
    d.emoji("🍎", s.apple.x * CELL + CELL / 2, Y0 + s.apple.y * CELL + CELL / 2, 18);
    for (let i = 1; i < s.body.length; i++) {
      const p = s.body[i];
      d.rect(p.x * CELL + 1, Y0 + p.y * CELL + 1, CELL - 2, CELL - 2, "ink", { round: 6 });
    }
    const h = s.body[0];
    d.emoji("🐍", h.x * CELL + CELL / 2, Y0 + h.y * CELL + CELL / 2, 22);
  }
};

function reset(s, g) {
  s.body = [{ x: 6, y: 14 }, { x: 5, y: 14 }, { x: 4, y: 14 }];
  s.dir = { x: 1, y: 0 };
  s.next = { x: 1, y: 0 };
  s.wait = 0;
  placeApple(s, g);
}

function placeApple(s, g) {
  for (let tries = 0; tries < 200; tries++) {
    const a = { x: g.randInt(0, COLS - 1), y: g.randInt(0, ROWS - 1) };
    if (!s.body.some((p) => p.x === a.x && p.y === a.y)) { s.apple = a; return; }
  }
}

// Mau Mau gegen den Computer (nur Spiel-API, keine Importe). Runde: 5 Karten je Seite, passende Karte nach Farbe oder Rang.
// Jede Steuerung und jeder Tipp zeigt sofort eine Rueckmeldung (s.msg), damit nichts wirkungslos bleibt.
const RANKS = ["7", "8", "9", "10", "U", "O", "K", "A"];
const SUITS = ["♥", "♦", "♣", "♠"];
const ZUGLIMIT = 30, WARTE = 40, HALTEN = 12;

export default {
  title: "Mau Mau gegen den Computer",
  controls: ["left", "right", "up", "down", "fire"],
  lives: 1,

  init(g) {
    const deck = [];
    for (let f = 0; f < 4; f++) for (let r = 0; r < 8; r++) deck.push({ r, f });
    shuffle(deck, g);
    const hand = [], comp = [];
    for (let i = 0; i < 5; i++) { hand.push(deck.pop()); comp.push(deck.pop()); }
    const ablage = deck.pop();
    return { hand, comp, stapel: deck, ablage, cx: 0, zone: 0, halten: 0, phase: "du", warte: 0, zuegeS: 0, zuegeC: 0, ende: "", msg: "", msgT: 0, tasten: 0 };
  },

  update(s, input, g) {
    if (s.msgT > 0) { s.msgT -= 1; if (s.msgT === 0) s.msg = ""; }
    if (s.phase === "comp") {
      s.warte -= 1;
      if (s.warte <= 0) computerZug(s, g);
      return;
    }
    if (input.left || input.right || input.up || input.down) s.tasten += 1;
    if (input.up) s.zone = 1;
    else if (input.down) s.zone = 0;
    const dx = (input.right ? 1 : 0) - (input.left ? 1 : 0);
    if (dx !== 0 && s.zone === 0) {
      if (s.halten % HALTEN === 0) s.cx = g.clamp(s.cx + dx, 0, s.hand.length - 1);
      s.halten += 1;
    } else s.halten = 0;
    if (!input.firePressed || s.ende) return;
    if (s.zone === 0) spielerKarte(s, g);
    else spielerStapel(s, g);
  },

  draw(s, d, g) {
    d.clear("cream");
    const n = s.comp.length;
    const sp = Math.min(50, 300 / Math.max(1, n));
    for (let i = 0; i < n; i++) d.rect(20 + i * sp, 90, 46, 64, "ink", { round: 6 });
    d.text("Computer: " + n + " Karten", 20, 70, { size: 16 });

    if (s.zone === 1) d.rect(114, 294, 58, 76, "red", { round: 8 });
    d.rect(120, 300, 46, 64, "yellow", { round: 6, line: true });
    d.text(String(s.stapel.length), 143, 322, { size: 16, align: "center" });
    cardDraw(d, s.ablage, 180, 300);
    d.text(s.phase === "du" ? "Du am Zug" : "Computer am Zug", 180, 250, { size: 18, align: "center" });
    d.text("Züge: du " + s.zuegeS + " / " + ZUGLIMIT + ", Computer " + s.zuegeC, 180, 390, { size: 14, align: "center" });
    if (s.msg) d.text(s.msg, 180, 420, { size: 14, align: "center" });

    const hn = s.hand.length;
    const hsp = Math.min(50, 300 / Math.max(1, hn));
    for (let i = 0; i < hn; i++) {
      const x = 20 + i * hsp;
      if (s.zone === 0 && i === s.cx) d.rect(x - 3, 497, 52, 70, "red", { round: 8 });
      cardDraw(d, s.hand[i], x, 500);
    }
    d.text("Deine Karten", 20, 476, { size: 18 });

    if (s.ende) {
      d.rect(50, 230, 260, 70, "yellow", { round: 10, line: true });
      d.text(s.ende, 180, 262, { size: 20, align: "center" });
    }
  }
};

function shuffle(deck, g) {
  for (let i = deck.length - 1; i > 0; i--) {
    const j = g.randInt(0, i);
    const t = deck[i];
    deck[i] = deck[j];
    deck[j] = t;
  }
}

function passt(c, a) {
  return c.r === a.r || c.f === a.f;
}

function sag(s, text) {
  s.msg = text;
  s.msgT = 60;
}

function cardDraw(d, c, x, y) {
  const farbe = c.f === 0 || c.f === 1 ? "red" : "ink";
  d.rect(x, y, 46, 64, "cream", { round: 6, line: true });
  d.text(RANKS[c.r], x + 6, y + 8, { size: 14, color: "ink" });
  d.text(SUITS[c.f], x + 23, y + 30, { size: 22, color: farbe, align: "center" });
}

function spielerKarte(s, g) {
  const c = s.hand[s.cx];
  if (!c) return;
  if (!passt(c, s.ablage)) { sag(s, "Passt nicht zur Ablage"); return; }
  s.hand.splice(s.cx, 1);
  s.ablage = c;
  s.zuegeS += 1;
  s.msg = "";
  s.msgT = 0;
  g.addScore(5);
  g.sound("pop");
  if (s.hand.length === 0) {
    s.ende = "Du hast gewonnen";
    g.addScore(20);
    g.sound("win");
    g.win();
    return;
  }
  s.cx = g.clamp(s.cx, 0, s.hand.length - 1);
  if (s.zuegeS >= ZUGLIMIT) { s.ende = "Zuglimit erreicht"; g.gameOver(); return; }
  s.phase = "comp";
  s.warte = WARTE;
}

function spielerStapel(s, g) {
  if (s.hand.some((c) => passt(c, s.ablage))) { sag(s, "Du hast eine passende Karte"); return; }
  if (s.stapel.length === 0) { sag(s, "Stapel ist leer"); return; }
  s.zuegeS += 1;
  s.hand.push(s.stapel.pop());
  s.msg = "";
  s.msgT = 0;
  g.sound("pop");
  if (s.zuegeS >= ZUGLIMIT) { s.ende = "Zuglimit erreicht"; g.gameOver(); return; }
  s.phase = "comp";
  s.warte = WARTE;
}

function computerZug(s, g) {
  const idx = [];
  for (let i = 0; i < s.comp.length; i++) if (passt(s.comp[i], s.ablage)) idx.push(i);
  if (idx.length > 0) {
    const i = g.random() < 0.7 ? idx[0] : idx[g.randInt(0, idx.length - 1)];
    s.ablage = s.comp.splice(i, 1)[0];
    s.zuegeC += 1;
    g.sound("pop");
    if (s.comp.length === 0) { s.ende = "Computer hat gewonnen"; g.gameOver(); return; }
  } else {
    if (s.stapel.length > 0) s.comp.push(s.stapel.pop());
    s.zuegeC += 1;
  }
  if (s.zuegeC >= ZUGLIMIT) { s.ende = "Zuglimit erreicht"; g.gameOver(); return; }
  s.phase = "du";
}

// Segelboot-Wellen im Hafen (nur Spiel-API). Holzboote wandern in Reihen, Wasserbomben stoppen sie.
export default {
  title: "Segelboot-Wellen im Hafen",
  controls: ["left", "right", "fire"],
  lives: 3,

  init(g) {
    return { ship: { x: g.W / 2 - 20, y: 580, w: 40, h: 30 }, bombs: [], boats: fleet(g), drift: [], effekte: [], dir: -1, cool: 0, step: 0 };
  },

  update(s, input, g) {
    const ship = s.ship;
    if (input.left) ship.x -= 4;
    if (input.right) ship.x += 4;
    ship.x = g.clamp(ship.x, 4, g.W - 44);

    if (s.cool > 0) s.cool -= 1;
    if ((input.firePressed || input.fire) && s.cool === 0 && s.bombs.length < 3) {
      s.bombs.push({ x: ship.x + 20, y: ship.y, r: 7 });
      s.cool = 14;
      g.sound("shoot");
    }
    for (const b of s.bombs) b.y -= 8;
    s.bombs = s.bombs.filter((b) => b.y >= g.TOP);

    // Holzboote: seitwaerts, am Rand umkehren und eine Reihe tiefer
    const speed = 0.5 + 0.2 * g.level + (24 - s.boats.length) * 0.04;
    let edge = false;
    for (const b of s.boats) {
      b.x += s.dir * speed;
      if ((s.dir < 0 && b.x < 6) || (s.dir > 0 && b.x + b.w > g.W - 6)) edge = true;
    }
    if (edge) { s.dir = -s.dir; for (const b of s.boats) b.y += 14; }

    // Die Flotte rueckt auch ohne Treffer langsam vor (sonst wuerde sie nie das Ufer erreichen)
    s.step += 1;
    if (s.step >= 28) { s.step = 0; for (const b of s.boats) b.y += 14; }

    // Beruehrung des Segelboots oder untere Grenze beendet die Runde
    for (const b of s.boats) {
      if (b.y + b.h >= 560 || g.hit(ship, b)) { g.gameOver(); return; }
    }

    // Treffer: Bombe versenkt das Boot, es treibt weg
    for (const bomb of s.bombs) {
      for (const b of s.boats) {
        if (!b.sunk && g.hit(bomb, b)) {
          b.sunk = true;
          bomb.y = -100;
          g.addScore(1);
          g.sound("pop");
          s.drift.push({ x: b.x, y: b.y, w: b.w, h: b.h, t: 60 });
          s.effekte.push({ x: b.x + b.w / 2, y: b.y + b.h / 2, t: 10 });
          break;
        }
      }
    }
    s.bombs = s.bombs.filter((b) => b.y >= g.TOP);
    s.boats = s.boats.filter((b) => !b.sunk);

    for (const d of s.drift) { d.x -= 0.6; d.y += 1; d.t -= 1; }
    s.drift = s.drift.filter((d) => d.t > 0 && d.y < g.H);
    for (const e of s.effekte) e.t -= 1;
    s.effekte = s.effekte.filter((e) => e.t > 0);

    // Welle geschafft: naechste, schnellere Welle
    if (s.boats.length === 0) {
      g.nextLevel();
      g.sound("level");
      s.boats = fleet(g);
      s.dir = -1;
      s.bombs = [];
      s.step = 0;
    }
  },

  draw(s, d, g) {
    d.clear("cream");
    for (let y = 120; y < g.H; y += 60) d.line(0, y + (g.frame >> 3) % 6, g.W, y + (g.frame >> 3) % 6, "yellow", 2);
    for (const b of s.boats) d.emoji("🛶", b.x + b.w / 2, b.y + b.h / 2, 30);
    for (const t of s.drift) {
      d.rect(t.x, t.y, t.w, t.h, "red", { round: 8 });
      d.emoji("🛶", t.x + t.w / 2, t.y + t.h / 2, 20);
    }
    for (const e of s.effekte) {
      d.circle(e.x, e.y, 4 + (10 - e.t), "yellow");
      d.circle(e.x + 3, e.y - 3, 3 + (10 - e.t) / 2, "red");
    }
    for (const b of s.bombs) {
      d.circle(b.x, b.y, 11, "yellow");
      d.emoji("💧", b.x, b.y, 22);
    }
    d.emoji("⛵", s.ship.x + 20, s.ship.y + 15, 36);
  }
};

function fleet(g) {
  const out = [];
  const rows = Math.min(2 + g.level, 5);
  for (let r = 0; r < rows; r++) {
    for (let c = 0; c < 6; c++) out.push({ x: 20 + c * 52, y: g.TOP + 20 + r * 42, w: 34, h: 30, sunk: false });
  }
  return out;
}

// Ueberhol-Rennen: Spielauto wechselt zwischen zwei Spuren, andere Autos kommen von vorne.
// Start auf der rechten Spur, damit Links-Wechsel von Anfang an moeglich ist.
const LANES = [110, 250];
const PY = 520;

export default {
  title: "Überhol-Rennen auf der Autobahn",
  controls: ["left", "right", "up", "down"],
  lives: 5,

  init(g) {
    return { lane: 1, v: 4, sw: 12, cars: [], tick: 0, next: 90, safe: 0, off: 0 };
  },

  update(s, input, g) {
    s.sw += 1;
    if ((input.left || input.right) && s.sw >= 12) {
      const want = input.left ? 0 : 1;
      if (want !== s.lane) { s.lane = want; s.sw = 0; }
    }
    if (input.up) s.v = Math.min(8, s.v + 0.1);
    if (input.down) s.v = Math.max(2, s.v - 0.1);
    s.off += s.v;

    s.tick += 1;
    if (s.tick >= s.next) {
      s.tick = 0;
      s.next = 90 + g.randInt(0, 30);
      // Zufaellige Spur; meist die Spur neben dem Spielauto, damit Ueberholen moeglich ist
      let li = g.randInt(0, 1);
      if (li === s.lane && g.random() < 0.7) li = 1 - li;
      s.cars.push({ li, x: LANES[li], y: g.TOP - 40, passed: false, gone: false });
    }

    if (s.safe > 0) s.safe -= 1;
    const pl = { x: LANES[s.lane] - 20, y: PY - 30, w: 40, h: 60 };
    for (const c of s.cars) {
      if (c.gone) continue;
      c.y += 0.5 * s.v + 0.1 * g.level;
      if (!c.passed && c.y > PY + 60) {
        c.passed = true;
        if (c.li !== s.lane) { g.addScore(1); g.sound("pop"); }
        continue;
      }
      if (!c.passed && s.safe === 0 && g.hit(pl, { x: c.x - 18, y: c.y - 28, w: 36, h: 56 })) {
        c.gone = true;
        s.v = 2;
        s.safe = 60;
        g.sound("hurt");
        g.loseLife();
      }
    }
    s.cars = s.cars.filter((c) => !c.gone && c.y < g.H + 40);

    if (g.frame > 0 && g.frame % 600 === 0) { g.nextLevel(); g.sound("level"); }
  },

  draw(s, d, g) {
    d.clear("cream");
    d.rect(40, g.TOP, 280, g.H - g.TOP, "ink");
    d.rect(40, g.TOP, 4, g.H - g.TOP, "yellow");
    d.rect(316, g.TOP, 4, g.H - g.TOP, "yellow");
    for (let y = g.TOP - 60 + (s.off % 60); y < g.H; y += 60) d.rect(178, y, 4, 36, "yellow");
    for (const c of s.cars) d.emoji("🚙", c.x, c.y, 36);
    const px = LANES[s.lane];
    if (s.safe > 0) {
      const col = (s.safe >> 2) % 2 === 0 ? "red" : "cream";
      d.rect(px - 24, PY - 34, 48, 68, col, { round: 12 });
    }
    d.emoji("🏎️", px, PY, 40);
  }
};

// Seifenblasen-Raumschiff: Blasen platzen Felsen. Ein Felsen am Schiff beendet die Runde.
// Rekord-Anzeige fehlt: Die Spiel-API speichert nichts ueber die Runde hinaus.
const SPARK = ["yellow", "red", "ink"];

export default {
  title: "Seifenblasen-Raumschiff",
  controls: ["left", "right", "fire"],
  lives: 1,

  init() {
    return { ship: { x: 170, y: 580, w: 36, h: 30 }, bubbles: [], rocks: [], sparks: [], cool: 0 };
  },

  update(s, input, g) {
    const ship = s.ship;
    if (input.left) ship.x -= 4;
    if (input.right) ship.x += 4;
    ship.x = g.clamp(ship.x, 0, g.W - ship.w);

    if (s.cool > 0) s.cool -= 1;
    if ((input.firePressed || input.fire) && s.cool === 0 && s.bubbles.length < 4) {
      s.bubbles.push({ x: ship.x + ship.w / 2, y: ship.y - 20, r: 8 });
      s.cool = 10;
      g.sound("shoot");
    }
    for (const b of s.bubbles) b.y -= 6;
    s.bubbles = s.bubbles.filter((b) => b.y >= g.TOP);

    if (g.frame % 45 === 0 || g.random() < 0.01) {
      const r = g.randInt(0, 1) === 0 ? 12 : 22;
      s.rocks.push({ x: g.randInt(20, 340), y: g.TOP - 20, r, dead: false });
    }
    const v = Math.min(4, 1.5 + 0.01 * g.frame);
    for (const r of s.rocks) r.y += v;

    for (const b of s.bubbles) {
      for (const r of s.rocks) {
        if (!r.dead && g.dist(b, r) < b.r + r.r) {
          b.dead = true;
          r.dead = true;
          g.addScore(1);
          g.sound("pop");
          for (let k = 0; k < 8; k++) {
            const a = k * 45;
            s.sparks.push({ x: r.x, y: r.y, dx: g.cos(a) * 2.5, dy: g.sin(a) * 2.5, r: 3, c: SPARK[k % 3], t: 20 });
          }
          break;
        }
      }
    }
    s.bubbles = s.bubbles.filter((b) => !b.dead);
    s.rocks = s.rocks.filter((r) => !r.dead && r.y - r.r <= g.H);

    for (const r of s.rocks) {
      const cx = g.clamp(r.x, ship.x, ship.x + ship.w);
      const cy = g.clamp(r.y, ship.y, ship.y + ship.h);
      const dx = r.x - cx, dy = r.y - cy;
      if (dx * dx + dy * dy < r.r * r.r) {
        g.sound("hurt");
        g.loseLife();
        return;
      }
    }

    for (const sp of s.sparks) { sp.x += sp.dx; sp.y += sp.dy; sp.t -= 1; }
    s.sparks = s.sparks.filter((sp) => sp.t > 0);

    if (g.frame > 0 && g.frame % 600 === 0) { g.nextLevel(); g.sound("level"); }
  },

  draw(s, d) {
    d.clear("cream");
    for (const r of s.rocks) d.emoji("🌑", r.x, r.y, r.r * 2 + 8);
    // Bereite Blase am Bug, solange keine Blase unterwegs ist
    if (s.bubbles.length === 0 && s.cool === 0) d.emoji("🫧", s.ship.x + s.ship.w / 2, s.ship.y - 20, 22);
    for (const b of s.bubbles) d.emoji("🫧", b.x, b.y, 22);
    for (const sp of s.sparks) d.circle(sp.x, sp.y, sp.r, sp.c);
    d.emoji("🚀", s.ship.x + 18, s.ship.y + 15, 36);
  }
};

// Katze auf den Daechern: Jump and Run ueber Daecher, Fischgraeten sammeln, Luecken sind toedlich.
const GRAV = 0.5, CAT = 26, CATX = 60, SPRUNG = -9, BOOST = 14;

export default {
  title: "Katze auf den Dächern",
  controls: ["fire"],
  lives: 1,

  init(g) {
    return {
      cat: { x: CATX, y: 534, vy: 0, ground: true, boost: 0 },
      roofs: [{ x: 0, y: 560, w: 360 }],
      bones: [{ x: 180, y: 538, r: 11 }],
      scroll: 2
    };
  },

  update(s, input, g) {
    const c = s.cat;

    // Sprung und Hochhalten (langer Druck springt hoeher)
    if (input.firePressed && c.ground) {
      c.vy = SPRUNG; c.boost = BOOST; c.ground = false; g.sound("jump");
    } else if (input.fire && c.boost > 0 && c.vy < 0) {
      c.vy -= 0.45; c.boost -= 1;
    } else {
      c.boost = 0;
    }

    // Schwerkraft und Bewegung
    const feet = c.y + CAT;
    c.vy = Math.min(c.vy + GRAV, 12);
    c.y += c.vy;
    c.ground = false;
    if (c.vy >= 0) {
      for (const r of s.roofs) {
        if (feet <= r.y + 0.01 && c.y + CAT >= r.y && c.x + CAT > r.x && c.x < r.x + r.w) {
          c.y = r.y - CAT; c.vy = 0; c.ground = true; c.boost = 0;
          break;
        }
      }
    }

    // Neue Daecher und Graeten rechts anlegen
    let last = 0;
    for (const r of s.roofs) if (r.x + r.w > last) last = r.x + r.w;
    while (last < g.W + 20) {
      const x = last + g.randInt(50, 95);
      const w = g.randInt(90, 170);
      const y = g.randInt(440, 580);
      s.roofs.push({ x, y, w });
      if (g.random() < 0.5) s.bones.push({ x: x + w / 2, y: y - 22, r: 11 });
      last = x + w;
    }

    // Scrollen nach links
    const sc = 2 + 0.3 * g.level;
    for (const r of s.roofs) r.x -= sc;
    for (const b of s.bones) b.x -= sc;
    s.roofs = s.roofs.filter((r) => r.x + r.w >= 0);

    // Graeten einsammeln
    const katze = { x: c.x, y: c.y, w: CAT, h: CAT };
    s.bones = s.bones.filter((b) => {
      if (g.hit(katze, b)) { g.addScore(1); g.sound("coin"); return false; }
      return b.x > -20;
    });

    // Level alle 600 Frames
    if (g.frame > 0 && g.frame % 600 === 0) { g.nextLevel(); g.sound("level"); }

    // Fallen in eine Luecke
    if (c.y > g.H) { g.sound("hurt"); g.loseLife(); }
  },

  draw(s, d, g) {
    d.clear("cream");
    for (const r of s.roofs) d.rect(r.x, r.y, r.w, 24, "yellow", { round: 8, line: true });
    for (const b of s.bones) d.emoji("🐟", b.x, b.y, 22);
    d.emoji("🐱", s.cat.x + CAT / 2, s.cat.y + CAT / 2, 28);
  }
};

// Wuerfelrunde fuer vier am Tisch: Reihum wuerfeln, 1 setzt die Rundenpunkte auf 0, 6 gibt einen Bonuswurf.
const FIG = ["🐸", "🐢", "🍓", "🎈"];
const NAMEN = ["Person 1", "Person 2", "Person 3", "Person 4"];
const ZIEL = 100, ZUGLIMIT = 200;

export default {
  title: "Würfelrunde für vier am Tisch",
  controls: ["fire"],
  lives: 1,

  init(g) {
    return {
      spieler: [0, 1, 2, 3].map(() => ({ total: 0, turn: 0 })),
      aktuell: 0, sieger: -1, bonus: false, zuege: 0, wurf: 0
    };
  },

  update(s, input, g) {
    if (s.sieger !== -1 || !input.firePressed) return;
    const v = g.randInt(1, 6);
    const p = s.spieler[s.aktuell];
    s.zuege += 1;
    s.wurf = v;
    if (v === 1) {
      p.total -= p.turn; p.turn = 0; s.bonus = false;
      g.sound("pop");
      s.aktuell = (s.aktuell + 1) % 4;
    } else if (v === 6) {
      p.total += 6; p.turn += 6; s.bonus = true;
      g.addScore(6); g.sound("coin");
    } else {
      p.total += v; p.turn = 0; s.bonus = false;
      g.addScore(v); g.sound("coin");
      s.aktuell = (s.aktuell + 1) % 4;
    }
    if (p.total >= ZIEL) { s.sieger = s.spieler.indexOf(p); g.win(); return; }
    if (s.zuege >= ZUGLIMIT) g.gameOver();
  },

  draw(s, d, g) {
    d.clear("cream");
    for (let i = 0; i < 4; i++) {
      const y = 60 + i * 62, p = s.spieler[i];
      if (i === s.aktuell && s.sieger === -1) d.rect(16, y - 4, 328, 62, "red", { round: 14 });
      d.rect(20, y, 320, 54, "yellow", { round: 12, line: true });
      d.emoji(FIG[i], 52, y + 27, 36);
      d.text(NAMEN[i], 84, y + 20, { size: 20, color: "ink", align: "left" });
      d.text(String(p.total), 332, y + 20, { size: 20, color: "ink", align: "right" });
    }
    d.text(s.wurf > 0 ? String(s.wurf) : "-", 180, 390, { size: 64, color: "ink", align: "center" });
    d.rect(60, 470, 240, 80, "red", { round: 20, shadow: true });
    d.text("Würfeln", 180, 500, { size: 28, color: "cream", align: "center" });
    if (s.sieger >= 0) d.text("Person " + (s.sieger + 1) + " gewinnt", 180, 590, { size: 24, color: "red", align: "center" });
    else d.text("Dran: " + NAMEN[s.aktuell], 180, 590, { size: 20, color: "ink", align: "center" });
  }
};

// Pong-Tennis: Schlaeger links (du) gegen Computer-Schlaeger rechts. Ball prallt ab, wer verpasst, gibt einen Punkt ab.
// Zeitlimit: nach 1140 Frames endet die Partie, wer mehr Punkte hat, gewinnt.
const PX = 40, CX = 320, PH = 90, BR = 8, SPEED = 4, ZEIT = 1140;

export default {
  title: "Pong-Tennis gegen den Computer",
  controls: ["up", "down"],
  lives: 1,

  init(g) {
    return { py: 320, cy: 320, off: 0, t: 0, bx: 180, by: 320, vx: g.randInt(0, 1) === 0 ? SPEED : -SPEED, vy: g.randInt(-2, 2), me: 0, cpu: 0 };
  },

  update(s, input, g) {
    if (input.up) s.py -= 5;
    if (input.down) s.py += 5;
    s.py = g.clamp(s.py, 60, 600);

    s.t += 1;
    if (s.t % 60 === 0) s.off = g.randInt(-40, 40);
    const step = g.clamp(s.by + s.off - s.cy, -3, 3);
    s.cy = g.clamp(s.cy + step, 60, 600);

    s.bx += s.vx;
    s.by += s.vy;
    if (s.by <= 56) { s.by = 56; s.vy = Math.abs(s.vy); }
    if (s.by >= 632) { s.by = 632; s.vy = -Math.abs(s.vy); }

    if (s.vx < 0 && s.bx <= 48 && Math.abs(s.by - s.py) <= 50) {
      s.vx = SPEED; s.bx = 48; g.addScore(1); g.sound("hit");
    } else if (s.vx > 0 && s.bx >= 312 && Math.abs(s.by - s.cy) <= 50) {
      s.vx = -SPEED; s.bx = 312; g.sound("hit");
    }

    if (s.bx < 0) {
      s.cpu += 1; g.sound("hurt"); serve(s, g, SPEED);
    } else if (s.bx > 360) {
      s.me += 1; g.addScore(5); g.sound("coin"); serve(s, g, -SPEED);
    }

    if (s.cpu >= 7) { g.gameOver(); return; }
    if (s.me >= 7) { g.win(); return; }
    if (g.frame >= ZEIT) {
      if (s.me > s.cpu) g.win(); else g.gameOver();
    }
  },

  draw(s, d) {
    d.clear("cream");
    d.line(180, 56, 180, 632, "yellow", 2);
    d.text(String(s.me), 150, 28, { size: 24, color: "ink", align: "center" });
    d.text(String(s.cpu), 210, 28, { size: 24, color: "ink", align: "center" });
    d.emoji("🏓", PX, s.py, 40);
    d.emoji("🤖", CX, s.cy, 40);
    d.emoji("🎾", s.bx, s.by, 20);
  }
};

function serve(s, g, vx) {
  s.bx = 180; s.by = 320; s.vx = vx; s.vy = g.randInt(-2, 2);
}

// Wasserballon-Duell: zwei Boote am Teich, Zug fuer Zug auf einem Geraet. Treffer aufs Segel zaehlt einen Punkt.
const YS = [500, 250], V = 10, G = 0.15, LIFE = 90, ZUGE = 30, TREFFER = 5;

function fresh() {
  return { x: [20, 300], y: [YS[0], YS[1]], wer: 0, zug: 0, treffer: [0, 0], ang: [60, 60], acool: 0, ballon: null, pop: null, kippen: [0, 0], ende: 0 };
}
function reset(s) {
  const f = fresh();
  for (const k of Object.keys(f)) s[k] = f[k];
}

export default {
  title: "Wasserballon-Duell auf dem Teich",
  controls: ["left", "right", "up", "down", "fire"],
  lives: 1,

  init() {
    return fresh();
  },

  update(s, input, g) {
    if (s.ende !== 0) { if (input.firePressed) reset(s); return; }
    for (let i = 0; i < 2; i++) if (s.kippen[i] > 0) s.kippen[i] -= 1;
    if (s.pop) { s.pop.t -= 1; if (s.pop.t <= 0) s.pop = null; }
    if (s.ballon) { flight(s, g); return; }

    const w = s.wer;
    if (input.left) s.x[w] = g.clamp(s.x[w] - 4, 0, g.W - 40);
    if (input.right) s.x[w] = g.clamp(s.x[w] + 4, 0, g.W - 40);
    if (input.up || input.down) {
      if (s.acool === 0) { s.ang[w] = g.clamp(s.ang[w] + (input.up ? 1 : -1), 20, 70); s.acool = 6; }
      else s.acool -= 1;
    } else s.acool = 0;

    if (input.firePressed) {
      const dir = w === 0 ? 1 : -1, a = s.ang[w];
      s.ballon = { x: s.x[w] + (dir > 0 ? 40 : 0), y: YS[w] + 8, vx: dir * V * g.cos(a), vy: -V * g.sin(a), n: 0 };
      s.zug += 1;
      g.sound("shoot");
    }
  },

  draw(s, d, g) {
    d.clear("cream");
    d.rect(10, 60, 340, 570, "yellow", { round: 16, line: true });
    d.text("Treffer " + s.treffer[0] + " : " + s.treffer[1] + "   Zug " + s.zug + " / " + ZUGE, g.W / 2, 74, { size: 18, align: "center", color: "ink" });
    d.text("Am Zug: Spieler " + (s.wer + 1), g.W / 2, 98, { size: 18, align: "center", color: "ink" });

    for (let i = 0; i < 2; i++) {
      const bx = s.x[i], by = YS[i];
      d.emoji("⛵", bx + 20, by + 15, 36);
      if (s.kippen[i] > 0) d.line(bx - 4, by + 24, bx + 44, by + (s.kippen[i] > 15 ? 4 : 28), "red", 3);
    }

    if (!s.ballon && s.ende === 0) {
      const w = s.wer, dir = w === 0 ? 1 : -1, a = s.ang[w];
      const tx = s.x[w] + (dir > 0 ? 40 : 0), ty = YS[w] + 8;
      d.line(tx, ty, tx + dir * 60 * g.cos(a), ty - 60 * g.sin(a), "red", 3);
      d.text(a + "°", tx + dir * 20, ty - 70, { size: 16, align: "center", color: "red" });
    }

    if (s.ballon) d.emoji("🎈", s.ballon.x, s.ballon.y, 22);
    if (s.pop) {
      d.circle(s.pop.x, s.pop.y, 4 + (20 - s.pop.t) * 1.2, "yellow", { line: true });
      d.emoji("💦", s.pop.x, s.pop.y, 28);
    }

    if (s.ende === 1 || s.ende === 2) {
      d.emoji("🎉", g.W / 2, 330, 80);
      d.text("Spieler " + s.ende + " gewinnt!", g.W / 2, 400, { size: 24, align: "center", color: "ink" });
      d.text("fire: neues Duell", g.W / 2, 440, { size: 16, align: "center", color: "ink" });
    } else if (s.ende === 3) {
      d.text("Zuglimit erreicht", g.W / 2, 400, { size: 24, align: "center", color: "ink" });
      d.text("fire: neues Duell", g.W / 2, 440, { size: 16, align: "center", color: "ink" });
    }
  }
};

function flight(s, g) {
  const b = s.ballon, w = s.wer, t = 1 - w;
  b.n += 1;
  b.vy += G;
  b.x += b.vx;
  b.y += b.vy;
  if (g.hit({ x: b.x, y: b.y, r: 6 }, { x: s.x[t] + 20, y: YS[t] + 4, r: 14 })) {
    s.treffer[w] += 1;
    g.addScore(1);
    g.sound("pop");
    s.pop = { x: b.x, y: b.y, t: 20 };
    s.kippen[t] = 30;
    s.ballon = null;
    s.wer = t;
    if (s.treffer[w] >= TREFFER) { s.ende = w + 1; g.win(); return; }
  } else if (b.n >= LIFE || b.y >= g.H - 30 || b.x < -20 || b.x > g.W + 20) {
    s.ballon = null;
    s.wer = t;
  } else return;
  if (s.zug >= ZUGE) { s.ende = 3; g.gameOver(); }
}

// Schaetzspiel (Runden-Vorlage): Gummibaerchen zaehlen, 5 Runden, Computer schaetzt mit.
const RUNDEN = 5, KI_ZEIT = 30, AUSW = 90, WIEDERHOLEN = 12;

export default {
  title: "Gummibärchen-Schätzspiel",
  controls: ["up", "down", "fire"],
  lives: 1,

  init(g) {
    return { runde: 1, glas: g.randInt(10, 60), schaetzung: 20, ki: null, gesch: null, rt: 0, halten: 0,
      punkte: 0, ki_punkte: 0, info: "Schätze, wie viele Bärchen im Glas sind!", ende: false };
  },

  update(s, input, g) {
    if (s.ende) return;
    // Zahl aendern: sofort beim Druecken, dann alle WIEDERHOLEN Frames, solange gehalten
    const dir = (input.up ? 1 : 0) - (input.down ? 1 : 0);
    if (dir !== 0) {
      if (s.halten % WIEDERHOLEN === 0) s.schaetzung = g.clamp(s.schaetzung + dir, 0, 99);
      s.halten += 1;
    } else s.halten = 0;
    // Schaetzen: jede Bestaetigung gibt sofort 1 Punkt
    if (input.firePressed) {
      s.gesch = s.schaetzung;
      s.punkte += 1;
      g.addScore(1);
      g.sound("pop");
    }
    s.rt += 1;
    if (s.rt === KI_ZEIT && s.ki === null) s.ki = g.randInt(0, 99);
    if (s.rt >= AUSW) auswerten(s, g);
  },

  draw(s, d, g) {
    d.clear("cream");
    d.text("Runde " + s.runde + " von " + RUNDEN, g.W / 2, 90, { size: 22, align: "center" });
    d.emoji("🫙", 180, 300, 150);
    for (let i = 0; i < s.glas; i++) {
      const col = i % 8, row = Math.floor(i / 8);
      d.emoji("🐻", 128 + col * 14, 236 + row * 16, 16);
    }
    d.text("Deine Schätzung: " + s.schaetzung, g.W / 2, 130, { size: 22, align: "center" });
    d.text("Computer: " + (s.ki === null ? "schätzt noch ..." : s.ki), g.W / 2, 162, { size: 18, align: "center" });
    d.text(s.gesch === null ? "Du bist dran" : "Geschätzt, warte auf Auswertung", g.W / 2, 500, { size: 18, align: "center" });
    d.text("Hoch/runter: ändern, Feuer: schätzen", g.W / 2, 530, { size: 16, align: "center" });
    d.text("Du " + s.punkte + "  :  Computer " + s.ki_punkte, g.W / 2, 565, { size: 22, align: "center" });
    d.text(s.info, g.W / 2, 605, { size: 14, align: "center" });
  }
};

function auswerten(s, g) {
  const dSp = s.gesch === null ? 999 : Math.abs(s.gesch - s.glas);
  const dKi = Math.abs(s.ki - s.glas);
  let txt = "Glas: " + s.glas + ". ";
  if (dSp < dKi) { s.punkte += 10; g.addScore(10); txt += "Du bist näher dran (+10)."; }
  else if (dKi < dSp) { s.ki_punkte += 10; txt += "Computer ist näher dran (+10)."; }
  else { s.punkte += 5; g.addScore(5); s.ki_punkte += 5; txt += "Gleichstand (je +5)."; }
  s.info = txt;
  if (s.runde >= RUNDEN) {
    s.ende = true;
    if (s.punkte > s.ki_punkte) g.win(); else g.gameOver();
    return;
  }
  s.runde += 1;
  s.glas = g.randInt(10, 60);
  s.gesch = null;
  s.ki = null;
  s.rt = 0;
  s.halten = 0;
  g.sound("level");
}

// Mau Mau gegen den Computer (Runden-Kartenspiel, nur Spiel-API, keine Importe).
const FARBEN = ["🍎", "🍋", "🍀", "🌟"];
const ZIEL = 100, ZUEGE_MAX = 60, ZEIT_MAX = 2400, PAUSE = 120, WARTE = 40;

export default {
  title: "Mau Mau gegen den Computer",
  controls: ["left", "right", "up", "down", "fire"],
  lives: 1,

  init(g) {
    const s = { runde: 0, pts: 0, zuege: 0, msg: "", sieger: "", rest: 0, halten: 0, rich: 0, zog: false };
    deal(s, g);
    return s;
  },

  update(s, input, g) {
    // Zeit- und Zuglimit gelten immer, auch ohne Eingabe (Spielende ist sicher erreichbar)
    if (g.frame >= ZEIT_MAX || s.zuege >= ZUEGE_MAX) { g.gameOver(); return; }
    if (s.phase === "ende") {
      if (s.rest > 0) s.rest -= 1;
      else if (input.firePressed) deal(s, g);
      return;
    }
    if (s.phase === "comp") { computerZug(s, g); return; }
    spielerZug(s, input, g);
  },

  draw(s, d, g) {
    d.clear("cream");
    d.text("Du: " + s.pts + " Punkte", 12, 62, { size: 18, color: "ink" });
    d.text("Runde " + s.runde + " · Züge " + s.zuege + "/" + ZUEGE_MAX, 348, 62, { size: 13, color: "ink", align: "right" });
    d.text("Computer: " + s.comp.length + " Karten", 12, 84, { size: 14, color: "ink" });
    const nc = s.comp.length, spc = Math.min(48, Math.floor(330 / Math.max(1, nc)));
    for (let i = 0; i < nc; i++) d.rect(12 + i * spc, 96, 40, 56, "red", { round: 6, line: true });

    d.rect(90, 200, 70, 80, "red", { round: 8, line: true });
    d.text("Stapel " + s.stack.length, 125, 290, { size: 12, color: "ink", align: "center" });
    const top = s.disc[s.disc.length - 1];
    d.rect(200, 200, 70, 80, "cream", { round: 8, line: true });
    d.text(String(top.w), 214, 216, { size: 18, color: "ink" });
    d.emoji(FARBEN[top.f], 235, 250, 34);
    d.text("Ablage", 235, 290, { size: 12, color: "ink", align: "center" });

    d.text(s.msg, 180, 320, { size: 14, color: "ink", align: "center" });
    if (s.phase === "ende") {
      d.text(s.sieger === "du" ? "Du gewinnst die Runde!" : "Computer gewinnt die Runde.", 180, 360, { size: 20, color: "red", align: "center" });
      d.text("Punkte: " + s.pts, 180, 392, { size: 18, color: "ink", align: "center" });
      if (s.rest === 0) d.text("Feuer: nächste Runde", 180, 420, { size: 14, color: "ink", align: "center" });
    }

    d.text("Deine Karten", 12, 444, { size: 14, color: "ink" });
    const n = s.hand.length, sp = Math.min(56, Math.floor(340 / Math.max(1, n)));
    for (let i = 0; i < n; i++) {
      const c = s.hand[i], x = 12 + i * sp, y = 470;
      d.rect(x, y, 50, 96, "cream", { round: 8, line: true });
      d.text(String(c.w), x + 8, y + 20, { size: 18, color: "ink" });
      d.emoji(FARBEN[c.f], x + 25, y + 60, 28);
    }
    if (n > 0) {
      const x = 12 + s.cur * sp, y = 470;
      d.rect(x - 3, y - 3, 56, 3, "red"); d.rect(x - 3, y + 96, 56, 3, "red");
      d.rect(x - 3, y - 3, 3, 102, "red"); d.rect(x + 50, y - 3, 3, 102, "red");
    }
    d.text("Links/Rechts wählen · Feuer legt ab · Hoch/Runter zieht", 180, 600, { size: 11, color: "ink", align: "center" });
  }
};

function passt(a, b) {
  return a.f === b.f || a.w === b.w;
}

function shuffle(list, g) {
  for (let i = list.length - 1; i > 0; i--) {
    const j = g.randInt(0, i);
    const t = list[i]; list[i] = list[j]; list[j] = t;
  }
}

function deal(s, g) {
  const deck = [];
  for (let f = 0; f < 4; f++) for (let w = 1; w <= 7; w++) deck.push({ f, w });
  shuffle(deck, g);
  s.hand = deck.splice(0, 5);
  s.comp = deck.splice(0, 5);
  s.disc = [deck.pop()];
  s.stack = deck;
  s.runde += 1;
  s.cur = 0; s.halten = 0; s.rich = 0; s.zog = false; s.wait = 0;
  s.phase = "du";
  s.rest = 0; s.sieger = "";
  s.msg = "Lege eine passende Karte ab oder zieh.";
}

function ziehen(s, g, wer) {
  if (s.stack.length === 0 && s.disc.length > 1) {
    const alt = s.disc;
    const top = alt.pop();
    s.stack = alt;
    s.disc = [top];
    shuffle(s.stack, g);
  }
  if (s.stack.length === 0) return;
  const c = s.stack.pop();
  if (wer === "du") s.hand.push(c); else s.comp.push(c);
}

function pruefe(s, g) {
  if (s.pts >= ZIEL) g.win();
  else if (s.zuege >= ZUEGE_MAX) g.gameOver();
}

function ende(s, g, wer) {
  s.phase = "ende";
  s.sieger = wer;
  s.rest = PAUSE;
  if (wer === "du") { s.pts += 20; g.addScore(20); g.sound("win"); }
  else g.sound("lose");
  pruefe(s, g);
}

function spielerZug(s, input, g) {
  const n = s.hand.length;
  const dir = (input.right ? 1 : 0) - (input.left ? 1 : 0);
  if (dir !== 0) {
    if (dir !== s.rich || s.halten >= 12) { s.cur = g.clamp(s.cur + dir, 0, Math.max(0, n - 1)); s.halten = 0; }
    s.halten += 1;
  } else s.halten = 0;
  s.rich = dir;

  const top = s.disc[s.disc.length - 1];
  if (input.firePressed) {
    const c = s.hand[s.cur];
    if (c && passt(c, top)) {
      s.hand.splice(s.cur, 1);
      s.disc.push(c);
      s.pts += 5; g.addScore(5); g.sound("pop");
      s.msg = "Gut gelegt! Computer ist am Zug.";
      s.cur = g.clamp(s.cur, 0, Math.max(0, s.hand.length - 1));
      s.zuege += 1;
      if (s.hand.length === 0) ende(s, g, "du");
      else { s.phase = "comp"; s.wait = 0; pruefe(s, g); }
      return;
    }
    s.msg = "Passt nicht: gleiche Farbe oder Wert nötig.";
  }

  if ((input.up || input.down) && !s.zog) {
    if (s.hand.some((c) => passt(c, top))) {
      s.msg = "Du hast eine passende Karte, also nicht ziehen.";
    } else {
      ziehen(s, g, "du");
      s.msg = "Du ziehst eine Karte. Computer ist am Zug.";
      s.zuege += 1;
      s.phase = "comp"; s.wait = 0;
      pruefe(s, g);
    }
  }
  s.zog = !!(input.up || input.down);
}

function computerZug(s, g) {
  s.wait += 1;
  if (s.wait < WARTE) return;
  const top = s.disc[s.disc.length - 1];
  const idx = [];
  for (let i = 0; i < s.comp.length; i++) if (passt(s.comp[i], top)) idx.push(i);
  if (idx.length > 0) {
    const i = g.random() < 0.7 ? idx[0] : idx[g.randInt(0, idx.length - 1)];
    s.disc.push(s.comp.splice(i, 1)[0]);
    g.addScore(1); g.sound("pop");
    s.msg = "Computer legt eine Karte ab.";
    s.zuege += 1;
    if (s.comp.length === 0) { ende(s, g, "comp"); return; }
  } else {
    ziehen(s, g, "comp");
    g.addScore(1);
    s.msg = "Computer zieht eine Karte.";
    s.zuege += 1;
  }
  s.phase = "du"; s.wait = 0;
  pruefe(s, g);
}
